const AREAS=[
area({id:'sprakfilosofi',area_id:'filosofi_sprakfilosofi',title:'Språkfilosofi, mening og bruk',tagline:'Hvordan uttrykk får mening, viser til verden og brukes til å handle.',method:{id:'met_filosofi_semantisk_pragmatisk_analyse',title:'Semantisk-pragmatisk analyse',description:'Skiller uttrykkets semantiske innhold fra kontekst, talerintensjon, implikatur og illokusjonær kraft.',data_forms:['semantisk analyse','kontekstmatrise','språkhandlingsanalyse']},places:['universitet','bibliotek','rettsinstitusjon','mediearkiv'],articles:[
article({id:'em_filosofi_mening_referanse_sannhetsbetingelser',title:'Mening, referanse og sannhetsbetingelser',level:2,definition:'Hvordan språklige uttrykk kan ha mening og referere, og hvordan semantisk innhold forbindes med sannhetsbetingelser.',concepts:[
concept('spraklig_mening','Språklig mening','Det semantiske innholdet et uttrykk bidrar med i en språkbruk, skilt fra den enkelte talerens tilfeldige assosiasjoner.','Mening må skilles både fra referenten uttrykket eventuelt peker på og fra den pragmatiske virkningen en konkret ytring får i en situasjon.','Begrepet gjør det mulig å spørre om to uttrykk kan ha samme referent og likevel formidle forskjellig kognitivt innhold.'),
concept('semantisk_referanse','Semantisk referanse','Forholdet mellom et språklig uttrykk og den gjenstanden, personen, typen eller størrelsen uttrykket brukes til å vise til.','Referanse må skilles fra mening: et navn kan peke på samme objekt som et annet navn uten at uttrykkene derfor er semantisk utskiftbare i alle sammenhenger.','Begrepet bærer konflikten mellom deskriptive teorier og direkte referanseteorier om navn og bestemte beskrivelser.'),
concept('sannhetsbetingelse','Sannhetsbetingelse','De forhold i verden som må foreligge for at en sannhetsvurderbar setning skal være sann under en bestemt fortolkning.','Sannhetsbetingelser er ikke det samme som en metode for å avgjøre sannhet i praksis; en setning kan ha bestemte sannhetsbetingelser selv når vi ikke kan kontrollere dem direkte.','Begrepet kobler semantisk innhold til logisk struktur og gjør det mulig å sammenligne Fregeanske og Russellianske analyser med senere semantiske teorier.')],
methods:['met_filosofi_begrepsanalyse','met_filosofi_argumentrekonstruksjon'],hook:'fil_sprakfilosofi_01',thinkers:[T.frege,T.russell,T.kripke,T.wittgenstein],sources:['sep-meaning','sep-reference','sep-word-meaning'],anchors:['Frege','Russell','referanse','sannhetsbetingelser'],debate:'Frege og Russell etablerer rivaliserende analyser av hvordan mening og referanse henger sammen, mens Kripkes direkte-referansekritikk og Wittgensteins bruksperspektiv utfordrer at språklig innhold kan forstås gjennom én enkelt beskrivende modell.',problem:'Når «Morgenstjernen» og «Aftenstjernen» viser til Venus, gjenstår spørsmålet om hvorfor identitetsutsagnet kan være informativt. Filosofien om språk må forklare både hva uttrykk bidrar med til sannhetsbetingelser og hvordan talere kan lære noe av setninger der referenten allerede er den samme.',stakes:'Problemet er ikke bare terminologisk. En teori om mening må håndtere feilaktige beskrivelser, tomme navn, identitetsutsagn og utskifting i holdningsrapporter uten å forklare alt ved å anta at mening ganske enkelt er objektet det refereres til. Russell og Frege viser to ulike måter å analysere denne spenningen på.',contrast:'Kripkes kritikk av deskriptivismen skjerper konflikten ved å spørre hvordan navn kan være rigid designator på tvers av mulige situasjoner, mens Wittgenstein minner om at språkets funksjon ikke uttømmes av referanse og sannhetsbetingelser alene.',argument:[
'P1: Freges skille mellom Sinn og Bedeutung forklarer informativ identitet ved at to uttrykk kan ha samme referanse, men presentere referenten på forskjellige måter. Hvis mening bare var referanse, ville «Morgenstjernen er Aftenstjernen» ha samme kognitive verdi som «Morgenstjernen er Morgenstjernen», noe den åpenbart ikke har i en kunnskapssituasjon.',
'P2: Russells teori om bestemte beskrivelser viser samtidig at grammatisk overflate kan villede om logisk form. Setningen «den nåværende kongen av Frankrike er skallet» trenger ikke behandles som et navn på en ikke-eksisterende konge; den kan analyseres kvantifikasjonelt, slik at eksistens og entydighet blir deler av sannhetsbetingelsen.',
'P3: Kripkes Naming and Necessity utfordrer den sterke ideen om at et navn får sin referanse gjennom en beskrivelse taleren forbinder med navnet. Navn kan videreføres gjennom historisk-sosiale kjeder og være rigide selv når mange av talerens beskrivelser er feil; derfor kan referanse ikke reduseres til individuell beskrivelseskunnskap.',
'K: En adekvat språkfilosofi må derfor skille minst tre forklaringsoppgaver: hvordan et uttrykk refererer, hvilket semantisk innhold det bidrar med, og hvilke sannhetsbetingelser hele setningen får. Frege, Russell og Kripke er rivaler fordi de plasserer forklaringsarbeidet på forskjellige nivåer, ikke fordi de bare bruker ulike ord.'
],objection:'Innvending: Wittgensteins senere filosofi kan tolkes som en advarsel mot hele prosjektet med å lete etter én skjult semantisk mekanisme bak alle uttrykk. Betydning viser seg i bruk innen språkspill, og mange filosofiske problemer oppstår når ord trekkes ut av praksisene som gir dem funksjon.',reply:'Svar: Bruksperspektivet gjør ikke referanse- og sannhetsbetingelsesproblemer irrelevante. Det viser snarere at semantisk teori må angi sitt forklaringsnivå. Når vi analyserer navn, beskrivelser eller logiske forbindelser, kan formell semantikk være presis; når vi analyserer hva en ytring gjør i praksis, må bruk, kontekst og normer inn uten at nivåene blandes.',stress:'Et godt stresstilfelle er et navn på en person der taleren har flere feilaktige beskrivelser, men likevel deltar i en etablert navnepraksis. Fregeansk beskrivelsesinnhold, Russelliansk logisk analyse og Kripkeansk kausal-historisk referanse gir forskjellige forklaringer på hva som lykkes og hva som kan være feil.',theoryNotes:['Frege bruker skillet mellom sans og referanse for å forklare informativ identitet og hvordan tankens innhold kan være mer finmasket enn ekstensional likhet.','Russell viser i On Denoting hvordan bestemte beskrivelser kan analyseres som kvantifikasjonsstrukturer fremfor refererende navn, og gjør logisk form til et redskap mot ontologisk overbefolkning.','Kripke angriper deskriptiv identifikasjon gjennom modalargumenter og navnets historiske overføring, mens Wittgenstein trekker oppmerksomheten mot regelstyrt bruk og variasjonen mellom språkspill.'],methodNote:'Analysen bør ta én faktisk setning og skrive ut både mulig logisk form, referanseforhold og kontekst. Først da kan vi se om uenigheten handler om semantisk innhold, metasemantisk grunnlag eller pragmatisk bruk.',methodBoundary:'Formalisering kan avdekke struktur, men den kan ikke uten videre avgjøre hvilken teori om referanse eller mening som er riktig. Historiske påstander om hva Frege, Russell eller Kripke mente må dessuten holdes atskilt fra en nåtidig vurdering av teorienes forklaringskraft.',case:'Ta en offentlig tekst der et institusjonsnavn skifter betydning eller referanse over tid, for eksempel etter en fusjon. Man kan undersøke om samme ord refererer til samme institusjon, om beskrivende innhold endres, og hvilke sannhetsbetingelser historiske utsagn om institusjonen får.',caseTest:'Caset er bare filosofisk opplysende når dokumentasjonen først fastslår hvem eller hva navnet faktisk ble brukt om. Deretter kan rivalene testes på om de forklarer referanse gjennom beskrivelser, historisk kontinuitet eller regelstyrt bruk uten å bruke teorien som bevis for de empiriske fakta.',sourceNote:'Kildene om meaning, reference og word meaning dekker ulike deler av debatten og skal ikke brukes som tre kopier av samme autoritet. De støtter henholdsvis teorier om semantisk innhold, referansens mekanismer og spørsmål om ordmening og språkkompetanse.',empiricalBoundary:'En filosofisk sekundærkilde kan dokumentere hva en referanseteori innebærer, men ikke at et bestemt navn i et lokalt arkiv faktisk ble brukt med en bestemt institusjonell betydning. Slike brukspåstander trenger egne tekst- eller arkivkilder.',limit:'Artikkelen avgjør ikke om én generell teori om mening kan dekke alle språklige fenomener. Den avgrenser et sentralt semantisk problemfelt der referanse, kognitiv verdi og sannhetsbetingelser må holdes fra hverandre før pragmatiske spørsmål legges til.',mastery:'Universitetsdybde innebærer at leseren kan rekonstruere Frege–Russell-kontrasten, forklare Kripkes deskriptivismekritikk og vise med et konkret eksempel hvorfor «samme referent» ikke automatisk betyr «samme mening».'}),
article({id:'em_filosofi_sprakhandling_pragmatikk_regelfolging',title:'Språkhandling, pragmatikk og regelfølging',level:3,definition:'Hvordan ytringer utfører handlinger, formidler mer enn det som sies bokstavelig og inngår i normstyrte språkpraksiser.',concepts:[
concept('illokusjon','Illokusjon','Den handlingen en taler utfører i og med å ytre noe, som å love, advare, påstå, spørre eller erklære.','Illokusjon må skilles fra både setningens semantiske innhold og ytringens faktiske konsekvens for mottakeren; samme proposisjon kan fremføres med ulik illokusjonær kraft.','Begrepet gjør Austin og Searles språkhandlingsteori testbar på konkrete ytringer og institusjonelle prosedyrer.'),
concept('konversasjonell_implikatur','Konversasjonell implikatur','Innhold en taler rasjonelt kan forstås som å formidle uten at innholdet er en del av det som bokstavelig sies av setningen.','Implikatur må skilles fra semantisk entailment og konvensjonell betydning fordi den ofte kan avlyses, avhenger av kontekst og rekonstrueres gjennom forventninger til samarbeid.','Begrepet bærer Grices forklaring på hvordan samtaler kan være informative langt utover bokstavelig setningsinnhold.'),
concept('spraklig_regelfolging','Språklig regelfølging','At en språkpraksis videreføres på måter som kan vurderes som riktige eller uriktige innen en sosial og normativ praksis.','Regelfølging må skilles fra å ha en privat mental formel som mekanisk bestemmer alle fremtidige anvendelser; Wittgensteins problem handler nettopp om hva som gjør én fortsettelse riktig.','Begrepet knytter semantikk til praksis, normativitet og sosialt etablerte kriterier uten å redusere mening til flertallets faktiske vane.')],methods:['met_filosofi_begrepsanalyse','met_filosofi_stedsanalyse_dialog'],hook:'fil_sprakfilosofi_02',thinkers:[T.austinSpeech,T.searle,T.grice,T.wittgenstein],sources:['sep-speech-acts','sep-implicature','sep-wittgenstein'],anchors:['Austin','Grice','illokusjon','implikatur'],debate:'Austin og Searle analyserer hvordan ytringer kan være handlinger med illokusjonær kraft, Grice forklarer hvordan talere formidler implikatur utover det sagte, og Wittgenstein utfordrer forestillingen om at språklig korrekthet kan forankres i en rent privat regel.',problem:'En ytring kan være sannhetsvurderbar og samtidig gjøre noe: et løfte binder taleren, en dom avsagt på riktig måte kan endre institusjonell status, og en ironisk kommentar kan formidle det motsatte av den bokstavelige setningen. Språkfilosofien må derfor forklare både innhold, handling og kontekst.',stakes:'Hvis vi blander semantikk og pragmatikk, blir det uklart om et budskap følger av ordenes betydning, av konversasjonelle slutninger eller av en institusjonell konvensjon. Dette er særlig viktig i rett, politikk og offentlig kommunikasjon, der forskjellen mellom å beskrive, love, true og erklære kan ha normative følger.',contrast:'Austin og Searle fokuserer på språkhandlingens kraft og konstituerende regler; Grice på slutningen fra det sagte til det mente; Wittgenstein på hvordan standarder for riktig bruk oppstår i en praksis. De konkurrerer ikke om ett enkelt fenomen, men deres modeller møtes i spørsmålet om hva som gjør kommunikasjon normstyrt.',argument:[
'P1: Austins How to Do Things with Words viser at enkelte ytringer ikke bare rapporterer en handling, men kan utføre den når passende konvensjonelle og situasjonelle betingelser er oppfylt. Et løfte eller en institusjonell erklæring kan derfor ikke analyseres fullstendig ved bare å oppgi proposisjonens sannhetsbetingelser.',
'P2: Searle systematiserer denne innsikten ved å skille proposisjonelt innhold fra illokusjonær kraft og ved å analysere regler som gjør bestemte ytringer til løfter, påstander eller direktiver. Det forklarer hvorfor identiske ord kan utføre forskjellige handlinger avhengig av rolle, situasjon og aksepterte prosedyrer.',
'P3: Grice viser samtidig at mye kommunikasjon ikke ligger i den illokusjonære typen alene. Når en person svarer «jeg skal jobbe» på spørsmål om en fest, kan implikaturen om fravær rekonstrueres gjennom samarbeidsforventninger uten å være en logisk konsekvens av den uttalte setningen. Pragmatisk forståelse krever derfor slutning.',
'K: En samlet analyse må skille det som sies, den illokusjonære handlingen og det som impliseres. Austin, Searle og Grice gir komplementære, men delvis rivaliserende forklaringsmekanismer, mens Wittgensteins regelfølgingsproblem presser oss til å forklare hvordan normene for korrekt anvendelse kan være mer enn privat intensjon eller observerbar vane.'
],objection:'Innvending: Et detaljert skille mellom semantikk, illokusjon og implikatur kan gi inntrykk av at hvert bidrag kan lokaliseres entydig. Kontekstualister og relevansteoretikere har nettopp hevdet at skillet mellom det bokstavelig sagte og pragmatisk beriket innhold kan være mindre skarpt enn den klassiske modellen antyder.',reply:'Svar: Uskarpe grenser opphever ikke behovet for analytiske distinksjoner. De gjør dem til hypoteser som må begrunnes i hvert tilfelle. En analyse bør vise hva som kan avlyses, hva som følger av konvensjon, hvilke institusjonelle betingelser som er nødvendige, og hva mottakeren må slutte seg til for å forstå ytringen.',stress:'Wittgensteins regelfølgingsproblem skaper en dypere utfordring: enhver eksplisitt regel kan fortolkes på flere måter dersom korrekt anvendelse bare bestemmes av en ny regel i hodet. Språkets normativitet må derfor knyttes til praksiser der riktig og galt har stabil bruk, uten at sannhet reduseres til sosial enighet.',theoryNotes:['Austin bryter med en snever beskrivelsesmodell ved å analysere performativer og vilkårene for vellykkede språkhandlinger. Hans poeng er institusjonelt så vel som semantisk: hvem som taler, i hvilken situasjon og under hvilken prosedyre kan være avgjørende.','Searle videreutvikler språkhandlingsteorien gjennom systematiske skiller mellom innhold og kraft og gjennom konstitutive regler. Dette gjør det mulig å spørre hvilke regler som skaper den sosiale statusen en ytring kan få.','Grice analyserer talermening og implikatur som rasjonelle slutninger, mens Wittgenstein flytter fokus mot bruk og regelfølging. Sammen avdekker de spenningen mellom individuell kommunikativ intensjon og de sosiale normene som gjør intensjonen forståelig.'],methodNote:'En semantisk-pragmatisk analyse bør transkribere den aktuelle ytringen, skille bokstavelig innhold fra illokusjonær kraft og registrere hvilken kontekst som støtter en implikatur. Deretter kan man teste om fortolkningen kan avlyses eller endres uten å endre ordene.',methodBoundary:'Metoden må ikke lese talerens motiv direkte ut av en tekst. Talermening er en fortolkningshypotese som trenger kontekst, mens en institusjonell språkhandling kan kreve dokumentasjon av formelle roller og prosedyrer. Filosofisk teori kan ikke erstatte slik dokumentasjon.',case:'Et egnet dokumentert case er en offentlig beklagelse fra en institusjon. Man kan spørre om teksten faktisk utfører en beklagelse, hvilke forpliktelser som etableres, hva som impliseres om ansvar, og om institusjonens praksis gir ytringen den kraften ordene tilsynelatende har.',caseTest:'Caset kan sammenligne en formelt korrekt, men pragmatisk unnvikende beklagelse med en ytring som mangler standardfrasen «vi beklager», men tydelig erkjenner ansvar. Da blir skillet mellom formel, illokusjon, implikatur og sosial regel synlig uten at analysen reduseres til ordtelling.',sourceNote:'Speech Acts brukes til språkhandlingens struktur, Implicature til Grices og senere pragmatiske debatter, og Wittgenstein-kilden til bruk og regelfølging. Kildene dekker ulike mekanismer og gjør det mulig å kontrollere at de ikke slås sammen til én løs teori om «kontekst».',empiricalBoundary:'Om en konkret ytring fikk juridisk, organisatorisk eller sosial virkning er et empirisk spørsmål. Det må dokumenteres med rettskilder, institusjonelle regler eller samtidige kilder; språkfilosofien forklarer hva slags betingelser som er relevante, ikke at de faktisk var oppfylt.',limit:'Artikkelen hevder ikke at alle ytringer kan klassifiseres uten rest som semantikk eller pragmatikk. Den etablerer en arbeidsdeling som gjør uenigheter om grensen synlige og viser hvorfor språkets handlingsdimensjon ikke kan reduseres til sannhetsbetingelser.',mastery:'Universitetsdybde innebærer at leseren kan analysere én ytring med Austin, Searle og Grice, forklare Wittgensteins regelfølgingsutfordring og vise hvilke deler av fortolkningen som er språklige, pragmatiske og institusjonelle.'})]}),

area({id:'religionsfilosofi',area_id:'filosofi_religionsfilosofi',title:'Religionsfilosofi, gudsbegrep og tro',tagline:'Argumenter om Gud, ondskap, skjulthet og rasjonaliteten i religiøs tro.',method:{id:'met_filosofi_religionsfilosofisk_evidensvurdering',title:'Religionsfilosofisk evidensvurdering',description:'Rekonstruerer teistiske og antiteistiske argumenter og skiller logisk mulighet, evidensiell støtte og trosrasjonalitet.',data_forms:['argumentkart','evidensmatrise','modal analyse']},places:['universitet','bibliotek','religiøs institusjon','arkiv'],articles:[
article({id:'em_filosofi_gudsargumenter_nodvendighet_forklaring',title:'Gudsargumenter, kontingens og forklaring',level:2,definition:'Kosmologiske argumenter som går fra kontingens, årsak eller forklaringsbehov til en første grunn, nødvendig virkelighet eller teistisk forklaring.',concepts:[concept('kosmologisk_argument','Kosmologisk argument','En argumentfamilie som tar utgangspunkt i kontingens, avhengighet, årsaksforhold eller at noe eksisterer og søker en tilstrekkelig grunn utenfor den aktuelle rekken av avhengige forhold.','Et kosmologisk argument må skilles fra designargumenter og ontologiske argumenter: det starter ikke med orden eller med et rent gudsbegrep, men med påståtte trekk ved det som finnes.','Begrepet gjør det mulig å sammenligne Aquinas’ årsaks- og bevegelsesargumenter med Leibniz’ kontingens- og forklaringsargument på riktig premissnivå.'),concept('tilstrekkelig_grunn','Tilstrekkelig grunn','Prinsippet eller kravet om at fakta, hendelser eller eksistensforhold har en grunn eller forklaring som gjør forståelig hvorfor de er slik snarere enn annerledes.','Prinsippet må skilles fra den svakere påstanden at mange ting faktisk kan forklares. Det sterke prinsippet er en metafysisk tese og kan ikke bare forutsettes fordi forklaringer ofte lykkes i vitenskap.','Begrepet er sentralt hos Leibniz fordi argumentet fra kontingens trenger en bro fra «det finnes kontingente ting» til «den samlede kontingente virkeligheten krever forklaring».'),concept('kontingensargument','Kontingensargument','Et kosmologisk argument der kontingente ting eller fakta, som kunne ha vært annerledes eller ikke eksistert, brukes som grunnlag for å slutte til en ikke-kontingent forklaringsgrunn.','Kontingensargumentet må skilles fra et rent temporalt første-årsaksargument; det kan spørre etter grunn selv dersom universet ikke har en første hendelse i tid.','Begrepet gjør Humes og Kants innvendinger om totalitet, kausalitet og modal overgang direkte relevante for Leibniz’ begrunnelse.')],methods:['met_filosofi_argumentrekonstruksjon','met_filosofi_premissproving'],hook:'fil_religionsfilosofi_01',thinkers:[T.aquinas,T.leibniz,T.hume,T.kant],sources:['sep-cosmological-argument','sep-natural-theology','sep-philosophy-religion'],anchors:['Aquinas','Leibniz','kontingens','tilstrekkelig grunn'],debate:'Aquinas og Leibniz forsvarer ulike kosmologiske veier fra avhengighet eller kontingens til en grunnleggende forklaring, mens Hume og Kant utfordrer både forklaringsprinsippet og overgangen fra verdens trekk til et nødvendig eller guddommelig vesen.',problem:'Kosmologiske argumenter spør ikke bare hva som kom først, men hvorfor det overhodet finnes kontingente eller avhengige forhold. Det avgjørende filosofiske arbeidet ligger i overgangen fra lokale forklaringer til en påstand om at hele den kontingente virkeligheten trenger en annen type grunn.',stakes:'En svak rekonstruksjon sier bare at «alt må ha en årsak» og konkluderer med Gud. De klassiske argumentene er mer nyanserte: Aquinas bruker forskjellige avhengighetsformer, og Leibniz knytter kontingens til prinsippet om tilstrekkelig grunn. Kritikken må derfor treffe de faktiske premissene, ikke en lærebokkarikatur.',contrast:'Hume utfordrer om en forklaring av hver del etterlater et separat forklaringskrav for helheten, mens Kant problematiserer bruken av kategorier og modalitet utover mulig erfaring. Dermed kan en kritiker godta mange lokale forklaringer uten å godta den metafysiske slutningen.',argument:['P1: Leibniz’ kontingensargument begynner med at mange ting og fakta kunne ha vært annerledes eller ikke eksistert. Dersom slike kontingente fakta ikke inneholder den fulle grunnen til sin egen aktualitet, oppstår et forklaringsspørsmål som ikke besvares bare ved å peke på enda et kontingent ledd.','P2: Prinsippet om tilstrekkelig grunn gir overgangen fra denne kontingensen til kravet om en forklaringsgrunn. Argumentet blir derfor bare så sterkt som begrunnelsen for prinsippet og for påstanden om at det kan anvendes på den samlede kontingente virkeligheten, ikke bare på enkelte hendelser innenfor den.','P3: Humes dialoger utfordrer nettopp overgangen fra deler til helhet og spør hvorfor en komplett forklaring av hvert ledd ikke kan være nok, mens Kant bestrider at begrepene vi bruker om erfaringsverdenen uten videre legitimerer kunnskap om en nødvendig grunn utenfor den. Kritikken angriper argumentets bropremisser.','K: Aquinas og Leibniz kan derfor ikke forsvares ved å gjenta at «noe må ha startet alt». En universitetsrekonstruksjon må spesifisere hvilken form for avhengighet som står på spill, hvorfor regress eller brute fact avvises, og hva som eventuelt rettferdiggjør å identifisere en endelig forklaringsgrunn med Gud.'],objection:'Innvending: Selv om en nødvendig grunn skulle følge, synes konklusjonen å være langt svakere enn klassisk teisme. Et nødvendig faktum, en grunnleggende lov eller en ukjent metafysisk struktur kan kanskje fylle forklaringsrollen uten å være allvitende, god eller personlig.',reply:'Svar: Dette er en reell begrensning og ikke et retorisk problem som kan hoppes over. Kosmologiske argumenter kan inngå i et større kumulativt prosjekt, men de må bedømmes etter den konklusjonen premissene faktisk støtter. Ytterligere gudsattributter krever ytterligere argumenter.',stress:'Et ekstra stresstestpunkt gjelder «brute facts». Hvis kritikeren tillater at virkeligheten som helhet ganske enkelt er et grunnleggende faktum uten videre forklaring, må forsvareren vise hvorfor dette er mindre rasjonelt enn en nødvendig grunn. Da blir konflikten en dyp uenighet om forklaringens metafysiske rekkevidde.',theoryNotes:['Aquinas’ fem veier er ikke én homogen første-årsaksargumentasjon. De arbeider med bevegelse, effektiv årsak, kontingens og andre ordensformer, og må leses i den aristotelisk-skolastiske metafysikken som gir begrepene deres funksjon.','Leibniz gjør prinsippet om tilstrekkelig grunn eksplisitt og spør hvorfor det finnes noe snarere enn ingenting. Hans kontingensargument er derfor spesielt egnet til å skille temporal begynnelse fra modal avhengighet.','Hume og Kant representerer forskjellige kritiske strategier: Hume angriper slutninger og analogier i naturlig teologi, mens Kant undersøker grensene for ren fornufts bruk av årsak, nødvendighet og totalitet.'],methodNote:'Metoden bør skrive argumentet på premissnivå og merke hvert trinn som empirisk, modalt eller metafysisk. Da blir det synlig om en uenighet gjelder at universet er kontingent, prinsippet om tilstrekkelig grunn, regress eller identifikasjonen av en nødvendig grunn.','methodBoundary':'At vitenskapen forklarer en bestemt kosmologisk hendelse avgjør ikke alene om virkeligheten som helhet trenger en metafysisk forklaring. Omvendt gir et filosofisk kontingensargument ingen empirisk kosmologi og må ikke brukes som kilde til universets alder eller fysiske begynnelse.','case':'Et dokumentert case kan være en historisk utstilling om Big Bang der publikum møter påstanden «universet begynte, derfor må noe ha skapt det». Analysen kan skille den fysikalske teorien om tidlig kosmologi fra det filosofiske spørsmålet om kontingens og forklaring.','caseTest':'Caset tester om argumentet faktisk avhenger av en temporal begynnelse. Leibniz’ variant kan fortsatt formuleres selv med en evig kosmos, mens enkelte kalam-varianter ikke kan det. Slik hindres et naturvitenskapelig funn fra å bli behandlet som en ferdig metafysisk konklusjon.','sourceNote':'Cosmological Argument gir kart over argumenttypene og innvendingene, Natural Theology plasserer dem i en bredere begrunnelsestradisjon, og Philosophy of Religion gir forbindelser til gudsbegrep, tro og rivaliserende argumenter.','empiricalBoundary':'Filosofikildene dokumenterer argumentstrukturer og fortolkninger, ikke spesifikke fysikkpåstander. Enhver påstand om kosmologiske data må derfor belegges separat med fysikk- eller astronomikilder.','limit':'Artikkelen etablerer ikke at et kosmologisk argument lykkes eller mislykkes én gang for alle. Den etablerer hvilke bro-premisser og konklusjonsgrenser som må være eksplisitte før teist og kritiker faktisk diskuterer samme argument.','mastery':'Leseren skal kunne skille første-årsak fra kontingens, forklare hvorfor tilstrekkelig grunn er et omstridt premiss og formulere både Humes og Kants kritikk uten å redusere dem til påstanden «vi kan ikke vite noe». '}),
article({id:'em_filosofi_ondskap_skjulthet_religios_epistemologi',title:'Ondskap, guddommelig skjulthet og religiøs epistemologi',level:3,definition:'Hvordan lidelse og ikke-motvillig vantro utfordrer teisme, og hvilke epistemiske standarder som kan gjøre religiøs tro rasjonell eller urasjonell.',concepts:[concept('ondskapens_problem','Ondskapens problem','Argumentfamilien som spør hvordan omfattende eller tilsynelatende meningsløs lidelse kan forenes med en Gud som er allmektig, allvitende og fullkomment god.','Den logiske versjonen, som hevder inkonsistens, må skilles fra evidensielle versjoner som hevder at lidelsens karakter gjør teisme mindre sannsynlig.','Begrepet gjør Mackies logiske utfordring og nyere evidensielle argumenter sammenlignbare uten at Plantingas fri-vilje-forsvar feilaktig behandles som svar på alle versjoner.'),concept('guddommelig_skjulthet','Guddommelig skjulthet','Problemet som oppstår dersom en fullkomment kjærlig Gud forventes å gjøre en relasjon epistemisk tilgjengelig, samtidig som det finnes personer som uten motvilje mangler tro på Guds eksistens.','Skjulthet må skilles fra ondskapens problem: evidensen består her ikke primært i lidelse, men i fravær av den typen tilgjengelighet en bestemt teori om guddommelig kjærlighet ser ut til å forutsi.','Begrepet gjør Schellenbergs argument testbart gjennom premisser om kjærlighet, relasjonsmulighet og ikke-motvillig vantro.'),concept('religios_epistemologi','Religiøs epistemologi','Studiet av når religiøs tro, erfaring og vitnesbyrd kan være epistemisk begrunnet, rasjonelt tillatt eller kunnskapsbærende.','Religiøs epistemologi må skilles fra spørsmålet om en bestemt religion er sann; en tro kan være rasjonelt dannet uten at sannheten dermed er etablert, og omvendt kan sann tro mangle god begrunnelse.','Begrepet bærer konflikten mellom streng evidensialisme, pragmatiske forsvar og Plantingas reformerte epistemologi.')],methods:['met_filosofi_argumentrekonstruksjon','met_filosofi_reflektiv_likevekt'],hook:'fil_religionsfilosofi_02',thinkers:[T.mackie,T.plantinga,T.schellenberg,T.james],sources:['sep-problem-evil','sep-divine-hiddenness','sep-religion-epistemology'],anchors:['Mackie','Plantinga','skjulthet','religiøs epistemologi'],debate:'Mackies logiske problem om ondskap, Plantingas fri-vilje-forsvar, Schellenbergs argument fra guddommelig skjulthet og rivaliserende evidensialistiske eller reformert-epistemologiske teorier viser at teismens rasjonalitet må vurderes gjennom flere distinkte argumenter.',problem:'Religionsfilosofien må håndtere to forskjellige typer fravær: fraværet av forventet godhet i møte med alvorlig lidelse og fraværet av forventet guddommelig tilgjengelighet i møte med oppriktig vantro. Begge kan brukes som evidens mot teisme, men argumentstrukturen er forskjellig.',stakes:'Det er metodisk avgjørende å skille en logisk motsigelse fra en evidensiell sannsynlighetsvurdering. Hvis Plantinga viser at Gud og ondskap er logisk forenlige, følger det ikke at mengden og typen lidelse er epistemisk nøytral. Tilsvarende kan et svar på ondskap la skjulthetsargumentet stå urørt.',contrast:'Mackie presser teismens interne konsistens, Plantinga viser en mulig modell der fri vilje og Gud kan sameksistere med moralsk ondskap, Schellenberg argumenterer fra ikke-motvillig vantro, mens James og reformert epistemologi utfordrer hvor høyt evidenskravet må settes for religiøs tro.',argument:['P1: Mackies klassiske logiske problem hevder at allmakt, fullkommen godhet og ondskap ser ut til å danne en inkonsistent mengde når det legges til plausible forbindelsesprinsipper om at en god og mektig Gud vil eliminere ondskap så langt det er mulig. Argumentets styrke avhenger derfor av disse forbindelsespremissene.','P2: Plantingas fri-vilje-forsvar svarer på den logiske utfordringen ved å beskrive en mulig verden der vesentlig moralsk frihet har verdi og der Gud ikke kan garantere at frie skapninger alltid velger godt uten å fjerne den relevante friheten. Hvis modellen er mulig, er streng logisk inkonsistens ikke etablert.','P3: Schellenbergs skjulthetsargument åpner en annen front: dersom fullkommen kjærlighet innebærer å være åpen for personlig relasjon med enhver kapabel person, er vedvarende ikke-motvillig vantro vanskelig å forklare. Her er problemet ikke frihetens mulighet alene, men hvilken epistemisk tilgjengelighet kjærlighet burde produsere.','K: At Plantinga svekker én logisk versjon av ondskapens problem avgjør derfor ikke den evidensielle debatten eller skjulthetsproblemet. En samlet religiøs epistemologi må undersøke hvordan lidelse, erfaring, vitnesbyrd og fravær av tro endrer rasjonell credence, og hvilke bakgrunnsforventninger som gjør evidensen relevant.'],objection:'Innvending: Slike argumenter kan overvurdere menneskers evne til å vite hvilke grunner en guddommelig aktør kunne ha. Skeptisk teisme hevder at vår manglende innsikt i en tilstrekkelig grunn til lidelse ikke gir sterk evidens for at ingen slik grunn finnes.',reply:'Svar: Skeptisk teisme kan svekke enkelte inferenser fra «jeg ser ingen grunn» til «det finnes ingen grunn», men har en kostnad hvis den generaliseres. Dersom vi blir for skeptiske til våre vurderinger av hva en god aktør sannsynligvis ville tillate, kan også moralsk og religiøs resonnering miste betydelig kraft.',stress:'Religiøs epistemologi kompliserer bildet ytterligere. Plantinga hevder at gudstro kan være «properly basic» under riktige kognitive betingelser, mens evidensialister krever mer offentlig tilgjengelig støtte. William James forsvarer i enkelte eksistensielle valg en rett til å tro der evidensen ikke avgjør, men dette er ikke en generell lisens til ønsketenkning.',theoryNotes:['Mackie er viktig fordi han formulerer den logiske konflikten presist og dermed gjør forbindelsespremissene synlige. Senere diskusjon viser hvorfor det må skilles mellom logisk mulighet og hvor sannsynlig teisme fremstår gitt faktisk lidelse.','Plantingas God, Freedom, and Evil er et forsvar snarere enn en full teodicé: målet er å vise konsistens, ikke å identifisere Guds faktiske grunn til hver lidelse. I Warranted Christian Belief utvider han debatten til epistemisk warrant.','Schellenberg kobler guddommelig kjærlighet til åpenhet for relasjon og gjør ikke-motvillig vantro til egen evidens. James representerer en annen epistemisk tradisjon der beslutning under tvungen og levende usikkerhet kan ha normativ betydning.'],methodNote:'Lag tre separate argumentkart: logisk ondskap, evidensiell ondskap og skjulthet. Marker deretter hvilke svar som faktisk angriper hvilket premiss. Først etter denne separasjonen bør en samlet evidensvurdering forsøkes.','methodBoundary':'Personlige erfaringer kan inngå i religiøs epistemologi, men en filosofiartikkel kan ikke validere en åpenbaring som empirisk faktum. Den kan analysere hvilken epistemisk rolle erfaringen får under forskjellige teorier om evidens og warrant.','case':'Et case kan være en offentlig minnemarkering etter katastrofe der religiøse og sekulære tolkninger av meningsløs lidelse uttrykkes side om side. Filosofisk analyse kan undersøke hvilke argumenter som faktisk fremsettes uten å rangere deltakernes sorg eller livssyn som mer autentisk.','caseTest':'Caset bør skille eksistensiell mening fra proposisjonell evidens. At en religiøs praksis hjelper noen gjennom sorg viser ikke i seg selv at teisme er sann; at en annen opplever guddommelig fravær viser heller ikke alene at teisme er falsk. Argumentene må rekonstrueres eksplisitt.','sourceNote':'Problem of Evil brukes til logiske og evidensielle argumenter, Divine Hiddenness til Schellenbergs argumentfamilie, og Epistemology of Religion til teorier om evidens, warrant, erfaring og vitnesbyrd.','empiricalBoundary':'Påstander om hvor utbredt ikke-motvillig vantro eller bestemte lidelsesformer er krever empiriske kilder dersom de skal brukes kvantitativt. SEP-kildene dokumenterer den filosofiske betydningen av slike fakta, ikke deres lokale forekomst.','limit':'Artikkelen etablerer ikke en totalsannsynlighet for eller mot teisme. Den viser hvorfor flere argumentfamilier ikke kan behandles som én og hvorfor et svar på logisk konsistens ikke automatisk besvarer evidens, skjulthet eller trosrasjonalitet.','mastery':'Leseren skal kunne forklare hva Plantingas forsvar faktisk viser, formulere Schellenbergs skjulthetsargument og skille rasjonalitet, warrant og sannhet i religiøs epistemologi.'})]}),

area({id:'rettsfilosofi',area_id:'filosofi_rettsfilosofi',title:'Rettsfilosofi, autoritet og fortolkning',tagline:'Hva lov er, hvorfor den kan forplikte og hvordan rettslig begrunnelse bør forstås.',method:{id:'met_filosofi_juridisk_fortolkningsanalyse',title:'Juridisk-filosofisk fortolkningsanalyse',description:'Skiller kilder til juridisk gyldighet, fortolkningsprinsipper og normative begrunnelser for rettslig autoritet.',data_forms:['rettskildematrise','fortolkningskart','normativ begrunnelsesanalyse']},places:['domstol','lovgivende institusjon','universitet','arkiv'],articles:[
article({id:'em_filosofi_rettens_natur_positivisme_naturrett',title:'Rettens natur: positivisme, naturrett og autoritet',level:2,definition:'Hva som gjør normer juridisk gyldige, og om lovens eksistens kan identifiseres gjennom sosiale fakta uten nødvendigvis å avgjøres av moralske meritter.',concepts:[concept('rettspositivisme','Rettspositivisme','Teorifamilien som hevder at lovens eksistens og innhold i siste instans beror på sosiale fakta, praksiser eller kilder og ikke på lovens moralske kvalitet som sådan.','Rettspositivisme må skilles fra moralsk relativisme og fra påstanden at dommere aldri bør bruke moralske grunner; tesen gjelder grunnlaget for juridisk gyldighet.','Begrepet gjør Austin og Hart sammenlignbare samtidig som forskjellen mellom kommando-, regel- og kildeteorier bevares.'),concept('naturrettsteori','Naturrettsteori','Teorifamilien som knytter forståelsen eller begrunnelsen av rett til praktisk fornuft, grunnleggende goder eller moralske standarder på en sterkere måte enn klassisk positivisme.','Naturrett må skilles fra slagordet «en urettferdig lov er ingen lov» fordi moderne naturrettsteorier kan anerkjenne positiv rett som juridisk artefakt og likevel hevde at lovens sentrale mening eller autoritet er normativ.','Begrepet bærer rivaliseringen mellom Fuller, Finnis og positivistiske modeller om lovens interne moral og praktiske autoritet.'),concept('anerkjennelsesregel','Anerkjennelsesregel','Harts begrep for den sosiale regelen blant rettens tjenestepersoner som angir kriterier for hvilke normer som teller som gyldig rett i et system.','Anerkjennelsesregelen må skilles fra en vedtatt grunnlovsparagraf: den kan være en praksis om hvilke kilder som aksepteres som autoritative og er selv en sosial regel på et annet nivå.','Begrepet gjør det mulig å forklare et rettssystem uten å redusere all rett til trusler fra en suveren og åpner samtidig spørsmålet om moral kan inngå i gyldighetskriteriene.')],methods:['met_filosofi_begrepsanalyse','met_filosofi_argumentrekonstruksjon'],hook:'fil_rettsfilosofi_01',thinkers:[T.johnAustin,T.hart,T.fuller,T.finnis],sources:['sep-legal-positivism','sep-natural-law-theories','sep-nature-law'],anchors:['Hart','positivisme','naturrett','anerkjennelsesregel'],debate:'Austin og Hart tilbyr positivistiske modeller av lov som sosialt institusjonelt fenomen, mens Fuller og Finnis utfordrer hvor langt lovens form, formål og moralske normativitet kan holdes utenfor en teori om hva rett er og hvorfor den gjør krav på autoritet.',problem:'En lov kan være moralsk dårlig og likevel håndheves som gyldig rett. Dette tilsynelatende enkle poenget reiser et grunnspørsmål: spør vi hva som faktisk er lov i et system, hva som gir loven autoritet, eller hva en lov burde være? Rettsfilosofien må holde disse spørsmålene sammen uten å blande dem.',stakes:'John Austins kommandoteori, Harts regelteori og moderne naturrett svarer forskjellig på hva som gjør et rettssystem til noe annet enn koordinert tvang. Dersom sosial praksis er nok for juridisk gyldighet, gjenstår normativ autoritet; dersom moral er nødvendig, må teorien forklare hvordan urettferdig positiv rett fortsatt kan identifiseres.',contrast:'Hart erstatter suverenens kommando med primære og sekundære regler og en anerkjennelsesregel. Fuller hevder at rettens form krever en intern legalitetsmoral, mens Finnis knytter rett til praktisk fornuft og felles gode. Konflikten gjelder både begrep og normativ forklaring.',argument:['P1: Austin gir en tidlig positivistisk modell der rett forstås gjennom kommando, suverenitet og sanksjon. Modellen forklarer tvang og institusjonell makt, men har problemer med kontinuitet, kompetansegivende regler og situasjoner der loven ikke ligner en ordre fra én identifiserbar suveren.','P2: Hart svarer ved å analysere rettssystemet som en union av primære pliktregler og sekundære regler om endring, avgjørelse og anerkjennelse. Anerkjennelsesregelen forklarer hvordan tjenestepersoners praksis kan etablere kriterier for gyldig rett uten å gjøre moral til et nødvendig gyldighetskriterium i alle systemer.','P3: Fuller og Finnis utfordrer om denne separasjonen fanger lovens normative karakter. Fuller fremhever legalitetskrav som generalitet, offentlighet og ikke-retroaktivitet, mens Finnis spør hvordan rettsordenen relateres til praktisk fornuft og felles gode. De bestrider at lovens sentrale formål kan beskrives normativt nøytralt.','K: Rettspositivisme og naturrett er derfor ikke best forstått som «lov versus moral». Striden gjelder hvilke fakta som grunnlegger juridisk gyldighet, hvilke normative egenskaper som er konstitutive for lov som institusjon, og om en teori om rettens natur kan skilles fra en teori om rettens praktiske autoritet.'],objection:'Innvending: Debatten kan virke verbal dersom positivisten tillater moralsk kritikk og naturrettsteoretikeren tillater at urettferdige regler juridisk sett eksisterer. Da synes partene bare å velge ulike definisjoner av «lov».',reply:'Svar: Uenigheten har substans fordi teoriene gir forskjellige forklaringer på vanskelige saker, rettslige feil og autoritet. Om moralske grunner kan være del av kriteriene for gyldighet, og om legalitetens form har nødvendig normativ betydning, påvirker hva teorien sier gjør en rettslig påstand sann.','stress':'Et stresstest-case er et diskriminerende lovvedtak som er proseduralt korrekt vedtatt. Positivisten kan identifisere det som gyldig og samtidig fordømme det moralsk. Naturrettsteoretikeren må presisere i hvilken forstand alvorlig urett svekker lovens autoritet eller status uten å late som institusjonen ikke eksisterer.',theoryNotes:['John Austin viser hvorfor tidlig positivisme ble knyttet til suveren kommando og sanksjon. Hans modell er viktig nettopp fordi Harts senere kritikk viser hvilke rettslige fenomener en ren kommandoteori har vanskelig for å forklare.','Harts The Concept of Law gjør anerkjennelsesregelen og skillet mellom primære og sekundære regler til kjerne. Dette er en sosial praksisteori, men ikke en teori om at all faktisk praksis er moralsk legitim.','Fullers The Morality of Law og Finnis’ Natural Law and Natural Rights representerer ulike ikke-positivistiske utfordringer. Fuller fokuserer på legalitetens form, Finnis på praktisk fornuft og grunnleggende goder; de skal derfor ikke slås sammen til én enkel naturrettsposisjon.'],methodNote:'En juridisk-filosofisk analyse bør først identifisere hva som er positiv rett i caset og hvilke kilder som brukes. Deretter kan man skille spørsmålet om gyldighet fra spørsmålet om normativ autoritet og teste hvilke premisser hver rettsteori trenger.','methodBoundary':'Rettsfilosofien kan analysere begrepet juridisk gyldighet, men den kan ikke uten jurisdiksjonsspesifikke rettskilder avgjøre hva gjeldende norsk, europeisk eller annen rett faktisk er. En konkret rettspåstand må derfor ha egen rettskildeproveniens.','case':'Et dokumentert case kan være en historisk lov som senere er kjent ugyldig eller opphevet på grunn av menneskerettslige eller konstitusjonelle normer. Analysen kan skille om loven var gyldig på tidspunktet fra om den hadde moralsk autoritet og fra hvorfor et senere system avviste den.','caseTest':'Caset bør brukes til å teste om teorien kan forklare rettslig kontinuitet, feil og kritikk uten å endre historiske fakta. Harts og Finnis’ modeller kan da sammenlignes på samme institusjonelle materiale i stedet for gjennom abstrakte slagord.','sourceNote':'Legal Positivism brukes til kildetesen og variasjonen innen positivismen, Natural Law Theories til moderne naturrett, og The Nature of Law til den bredere metajuridiske debatten om gyldighetsgrunnlag og normativitet.','empiricalBoundary':'SEP-kildene kan ikke dokumentere at en bestemt dom eller lov hadde et gitt rettslig innhold. Slike påstander må spores til lovtekst, dom, forarbeid eller pålitelig rettsvitenskap før de brukes som case-premiss.','limit':'Artikkelen løser ikke alle spørsmål om rettslig fortolkning eller straff. Den avgrenser grunnspørsmålet om lovens natur og autoritet slik at senere uenighet om domstolers metode kan bygges på et eksplisitt begrepsgrunnlag.','mastery':'Leseren skal kunne forklare hvorfor Hart ikke bare er Austin med nye ord, hvorfor naturrett ikke er synonymt med moralsk ønsketenkning, og hvordan en anerkjennelsesregel fungerer som sosialt gyldighetskriterium.'}),
article({id:'em_filosofi_rettstolkning_prinsipper_straff',title:'Rettstolkning, prinsipper og straffens begrunnelse',level:3,definition:'Hvordan dommere begrunner rettslige avgjørelser i vanskelige saker, og hvordan statens bruk av straff kan rettferdiggjøres eller utfordres.',concepts:[concept('rettslig_fortolkning','Rettslig fortolkning','Den begrunnede prosessen der tekst, prejudikater, formål, praksis og andre rettslige hensyn gis mening og vekt i avgjørelsen av hva retten krever.','Rettstolkning må skilles fra fri politisk preferanse og fra mekanisk tekstlesning; teorier er uenige om hvor mye juridisk innhold som allerede foreligger før normativ fortolkning.','Begrepet gjør Dworkins interpretivisme, positivistiske fortolkningsmodeller og koherenskrav sammenlignbare i samme vanskelige sak.'),concept('rettslig_prinsipp','Rettslig prinsipp','En normativ standard som kan ha rettslig relevans uten nødvendigvis å fungere som en alt-eller-intet-regel, og som kan inngå i begrunnelser for rettigheter og institusjonell praksis.','Prinsipp må skilles fra både moralsk verdi generelt og positiv regel; Dworkins poeng er at enkelte prinsipper kan være juridisk relevante gjennom den beste fortolkningen av praksisen.','Begrepet bærer konflikten om hvorvidt juridiske rettigheter kan bero på moralske prinsipper som ikke kan identifiseres bare gjennom kildepedigree.'),concept('straffebegrunnelse','Straffebegrunnelse','Den normative begrunnelsen for at staten med hensikt påfører en lovbryter byrder gjennom strafferettens institusjoner.','Straffebegrunnelse må skilles fra en årsaksforklaring på hvorfor stater faktisk straffer. Retributivisme, konsekvensialisme, kommunikative teorier og abolitionisme vurderer legitimiteten etter ulike kriterier.','Begrepet kobler rettsfilosofi til moral- og politisk filosofi og gjør det mulig å spørre om en gyldig strafferegel også kan brukes legitimt.')],methods:['met_filosofi_hermeneutisk_lesning','met_filosofi_normativ_sammenligning'],hook:'fil_rettsfilosofi_02',thinkers:[T.dworkin,T.hart,T.raz,T.duff],sources:['sep-law-interpretivist','sep-legal-reasoning','sep-legal-punishment'],anchors:['Dworkin','fortolkning','prinsipp','straff'],debate:'Dworkins interpretivisme utfordrer positivistiske beskrivelser av vanskelige rettssaker ved å gjøre moralske prinsipper del av den beste fortolkningen av institusjonell praksis, mens straffeteorien viser hvordan juridisk gyldighet og normativ legitimitet kan trekke i ulike retninger.',problem:'Domstoler møter saker der tekst, tidligere avgjørelser og rettslige formål ikke peker entydig samme vei. Spørsmålet er da om retten «går tom» og gir dommeren skjønn, eller om rettslige prinsipper allerede gir et bedre svar når institusjonell praksis fortolkes normativt.',stakes:'Straff viser hvorfor dette ikke er en abstrakt metodedebatt. Staten kan frata mennesker frihet og påføre byrder med hjemmel i retten. Selv når en regel er gyldig, må både fortolkningen av regelen og straffens begrunnelse tåle krav om rettferdighet, proporsjonalitet og autoritet.',contrast:'Dworkin hevder at rettigheter kan følge av prinsipper som best rettferdiggjør rettspraksis, mens Hart og Raz forsvarer ulike positivistiske rammer for kilder og autoritet. Duff viser på straffefeltet hvordan en kommunikativ begrunnelse skiller seg fra ren gjengjeldelse eller avskrekking.',argument:['P1: Dworkins kritikk av en enkel regelmodell tar utgangspunkt i vanskelige saker der etablerte regler ikke mekanisk avgjør resultatet, men der jurister likevel argumenterer som om noen prinsipper har rettslig vekt. Dette utfordrer tesen om at all juridisk normativitet må kunne identifiseres gjennom eksplisitt kildepedigree.','P2: Interpretivismen hevder at rettslige proposisjoner må forstås gjennom den fortolkningen som både passer institusjonell historie og rettferdiggjør den best. Moralske prinsipper får da ikke rettslig status fordi dommeren liker dem, men fordi de inngår i en konstruktiv fortolkning av praksisen som helhet.','P3: Positivister kan svare at en rettsorden selv kan gjøre moralske kriterier relevante, eller at dommere i uregulerte randsoner har rettsskapende skjønn. Konflikten blir derfor om moralens juridiske rolle er kontingent på sosiale kilder eller nødvendig for den beste forklaringen av rettslige rettigheter.','K: Når straff ilegges, blir skillet praktisk avgjørende: en dom må både være juridisk hjemlet og normativt forsvarlig. Dworkins prinsippbaserte rettsforståelse og Duffs kommunikative straffeteori viser på forskjellige nivåer hvorfor «gyldig regel» ikke alene avslutter spørsmålet om legitim tvang.'],objection:'Innvending: Interpretivisme kan gi dommere for stort rom til å importere egne moralske syn under etiketten «beste fortolkning». Hvis flere moralske teorier passer praksisen, kan rettens forutsigbarhet og demokratiske legitimitet svekkes.','reply':'Svar: Dworkins modell begrenser fortolkningen gjennom både fit og justification; institusjonell historie kan ikke overskrives fritt. Kritikken gjenstår likevel som et spørsmål om hvor determinerende disse kravene er, og positivisten kan hevde at eksplisitte kilder gir en mer transparent grense mellom rett og ny politikk.','stress':'Straffeteorien gir en separat innvending mot at et juridisk korrekt resultat automatisk er legitimt. Retributivister, konsekvensialister, kommunikative teorier og abolitionister er uenige om hva som kan rettferdiggjøre at staten med hensikt påfører byrder, og om enkelte systemiske skadevirkninger undergraver hele praksisen.',theoryNotes:['Dworkins Law’s Empire utvikler konstruktiv fortolkning og «law as integrity». Det sentrale er ikke at dommeren alltid velger det moralsk beste utfallet isolert, men at rettens institusjonelle historie fortolkes som en sammenhengende praksis av rettigheter og prinsipper.','Hart og Raz representerer ikke identiske positivismer. Hart åpner for at en anerkjennelsesregel kan gjøre moralske kriterier relevante, mens Raz’ eksklusive positivisme knytter lovens autoritet til kildeidentifiserbarhet på en strengere måte.','Duff utvikler en kommunikativ teori om straff der lovbryteren tiltales som ansvarlig borger. Denne modellen må sammenlignes både med retributiv fortjeneste, konsekvensialistisk avskrekking og abolitionistisk kritikk av straffeinstitusjonen.'],methodNote:'Fortolkningsanalysen bør lage en matrise over tekst, prejudikat, formål og prinsipper og vise hvilken vekt hver teori tillater. Straffespørsmålet bør deretter analyseres separat som en normativ legitimitetsvurdering, ikke skjules inne i rettskildebeskrivelsen.','methodBoundary':'Å si at Dworkin ville vektlegge et prinsipp er en filosofisk fortolkning; å si at en faktisk domstol gjorde det krever domstekst. På samme måte krever påstander om straffens empiriske avskrekkingseffekt samfunnsvitenskapelig evidens, ikke filosofi alene.','case':'Et egnet case er en høyesterettsavgjørelse der lovteksten er åpen og retten drøfter formål, tidligere praksis og grunnleggende rettigheter. Analysen kan først rekonstruere dommens egne grunner og deretter teste hvordan Dworkin, Hart eller Raz klassifiserer dem.','caseTest':'Dersom caset også gjelder straff eller sanksjon, kan en annen analyse spørre om tvangen er legitim etter retributiv, konsekvensialistisk og kommunikativ teori. Det hindrer rettskildeanalyse og straffeetikk i å bli blandet sammen som om de besvarte samme spørsmål.','sourceNote':'Legal Interpretivism dekker Dworkin-tradisjonen og dens rivaler, Legal Reasoning gir metodisk kontroll av fortolkning og koherens, og Legal Punishment dekker de normative teoriene om statlig straff.','empiricalBoundary':'Påstander om en konkret doms rettskilder, faktum eller rettsvirkning må belegges med primære rettskilder. Påstander om tilbakefall, avskrekking eller kriminalitetsutvikling krever empirisk forskning; straffefilosofien gir normative kriterier, ikke effektmål.','limit':'Artikkelen etablerer ikke en universell juridisk tolkningsmetode og tar ikke stilling til enhver strafferettslig institusjon. Den viser hvilke retts- og moralfilosofiske spørsmål som må holdes separate før en vanskelig sak kan vurderes.','mastery':'Leseren skal kunne rekonstruere Dworkins fit/justification-struktur, forklare positivistisk motstand og skille juridisk hjemmel fra normativ straffebegrunnelse i et dokumentert case.'})]}),

area({id:'matematikkfilosofi',area_id:'filosofi_matematikkfilosofi',title:'Matematikkfilosofi, objekter og bevis',tagline:'Hva matematiske objekter er, hvordan matematisk kunnskap er mulig og hva et bevis etablerer.',method:{id:'met_filosofi_matematisk_fundamentanalyse',title:'Matematisk fundamentanalyse',description:'Sammenligner ontologiske og epistemologiske forpliktelser i grunnlagsteorier og analyserer hva bevis og formalisering etablerer.',data_forms:['ontologimatrise','bevisanalyse','grunnlagskart']},places:['universitet','matematisk institutt','bibliotek','forskningsarkiv'],articles:[
article({id:'em_filosofi_matematiske_objekter_platonisme_nominalisme',title:'Matematiske objekter: platonisme, nominalisme og uunnværlighet',level:2,definition:'Om tall, mengder og andre matematiske objekter eksisterer uavhengig av oss, og hvordan vi i så fall kan ha kunnskap om dem.',concepts:[concept('matematisk_platonisme','Matematisk platonisme','Synet at det finnes abstrakte matematiske objekter som tall og mengder, og at deres eksistens og egenskaper ikke avhenger av menneskelig språk, tanke eller praksis.','Platonisme må skilles fra den historiske Platons samlede metafysikk; moderne matematisk platonisme er en spesifikk ontologisk tese om abstrakte matematiske entiteter.','Begrepet gjør Frege- og Gödel-inspirert realisme sammenlignbar med nominalistiske og strukturalistiske alternativer.'),concept('matematisk_nominalisme','Matematisk nominalisme','Strategier som forsøker å forstå matematisk språk, praksis eller vitenskapelig bruk uten ontologisk forpliktelse til abstrakte matematiske objekter.','Nominalisme må skilles fra påstanden at matematikk er falsk eller verdiløs; Field viser hvordan en nominalist kan respektere matematikkens instrumentelle rolle samtidig som ontologien utfordres.','Begrepet tvinger frem en forklaring på hvordan matematikk kan være anvendelig og konservativ uten at tall og mengder behandles som selvstendige ting.'),concept('uunngaelighetsargument','Uunnværlighetsargument','Argumenttypen, særlig knyttet til Quine og Putnam, som hevder at vi bør være ontologisk forpliktet til de matematiske entitetene som våre beste bekreftede vitenskapelige teorier uunnværlig kvantifiserer over.','Uunnværlighet må skilles fra ren praktisk bekvemmelighet; argumentet trenger at matematikkens rolle i vitenskapelig teori er både genuint uerstattelig og epistemisk koblet til bekreftelsen av teorien.','Begrepet kobler matematikkfilosofi til vitenskapsfilosofisk holisme og gjør Fields nominaliseringsprogram til en direkte rival.')],methods:['met_filosofi_begrepsanalyse','met_filosofi_abduktiv_vurdering'],hook:'fil_matematikkfilosofi_01',thinkers:[T.frege,T.godel,T.quine,T.field],sources:['sep-philosophy-mathematics','sep-platonism-mathematics','sep-nominalism-mathematics'],anchors:['platonisme','nominalisme','Quine','Field'],debate:'Frege- og Gödel-inspirert platonisme forklarer matematiske sannheter gjennom abstrakte objekter, Quines uunnværlighetsargument knytter ontologisk forpliktelse til vitenskap, og Fields nominalisme forsøker å bevare vitenskapelig anvendelighet uten abstrakt matematisk ontologi.',problem:'Matematiske utsagn synes både nødvendige og objektive, men objektene de handler om er ikke plassert i rom og tid slik fysiske objekter er. Hvis tallet to eksisterer abstrakt, oppstår spørsmålet om hvordan konkrete mennesker kan få epistemisk tilgang til det uten vanlig kausal kontakt.',stakes:'Platonisme lover en enkel sannhetsbetingelse: «2+2=4» er sant fordi matematiske objekter og relasjoner er slik. Nominalisme reduserer ontologien, men må forklare praksisens objektivitet og naturvitenskapens dype matematisering. Uunnværlighetsargumentet forsøker å gjøre vitenskapelig bekreftelse til bro mellom disse sidene.',contrast:'Frege gir språk og logikk ontologisk alvor, Gödel forsvarer matematisk realisme, Quine kobler ontologi til våre beste teorier, og Field prøver å nominalisere fysisk teori. Konflikten er både metafysisk og epistemologisk.',argument:['P1: Matematisk platonisme tilbyr en direkte realistisk forklaring på objektiv sannhet: numeriske og mengdeteoretiske utsagn handler om abstrakte objekter som eksisterer uavhengig av oss. Dette passer matematikkens tilsynelatende objektivitet, men skaper et epistemisk spørsmål fordi abstrakte objekter ikke inngår i vanlige kausale relasjoner.','P2: Quines uunnværlighetsargument forsøker å omgå et rent intuitivt «innsyn» i abstrakte objekter. Dersom vi bør tro på entitetene som våre beste bekreftede vitenskapelige teorier uunnværlig kvantifiserer over, og matematikk er uunnværlig der, får matematisk ontologi støtte gjennom samme holistiske bekreftelse som teorienes øvrige ontologi.','P3: Field utfordrer dette ved å vise hvordan betydelige deler av fysisk teori kan reformuleres nominalistisk og hvordan matematikk kan behandles som et konservativt hjelpemiddel. Hvis nominalisering kan lykkes uten tap av empirisk innhold, svekkes påstanden om at vitenskapens suksess krever tro på abstrakte objekter.','K: Debatten avgjøres derfor ikke ved å spørre om matematikere «snakker som om» tall finnes. Platonisme, uunnværlighet og nominalisme må sammenlignes på sannhetsforklaring, epistemisk tilgang, vitenskapelig anvendelse og kostnaden ved å rekonstruere teori uten abstrakte entiteter.'],objection:'Innvending: Field-lignende nominalisering kan være teknisk mulig, men virker explanatorisk kunstig og langt fra faktisk vitenskapelig praksis. Hvis de beste teoriene naturlig formuleres matematisk, kan kravet om en nominalistisk omskrivning se ut som ontologi drevet av forhåndspreferanse.',reply:'Svar: Nominalisten trenger ikke hevde at matematikere bør slutte å bruke matematikk. Poenget er å teste om anvendelsen tvinger frem ontologisk forpliktelse. Platonisten må på sin side forklare hvorfor praktisk og teoretisk uunnværlighet er nok til å etablere eksistens, ikke bare metodisk nytte.',stress:'Benacerraf-lignende utfordringer skjerper presset: dersom ulike set-teoretiske konstruksjoner kan spille rollen som tall, hva gjør én bestemt abstrakt struktur til «de egentlige» tallene? Strukturalistiske svar viser at valget ikke er begrenset til enkel objektplatonisme eller eliminativ nominalisme.',theoryNotes:['Frege søker objektivitet ved å knytte aritmetikk til logisk analyse og behandler talluttrykk som genuint refererende innen en realistisk semantikk. Hans prosjekt er samtidig historisk bakgrunn for både logicisme og moderne platonisme.','Gödel forbindes med en robust realisme der matematiske objekter og sannheter ikke skapes av formelle systemer. Ufullstendighetsresultatene brukes ofte i debatten, men må ikke overtolkes som et enkelt bevis for platonisme.','Quine gjør ontologisk forpliktelse avhengig av kvantifikasjon i våre beste teorier, mens Field forsøker å vise at matematikkens vitenskapelige rolle kan forklares uten at abstrakte objekter aksepteres som fysisk verdensbestand.'],methodNote:'Lag en matrise med kolonnene ontologi, sannhetsbetingelser, epistemisk tilgang og anvendelse i vitenskap. Plasser platonisme, uunnværlighetsargument og nominalisme i samme matrise slik at løsningen på ett problem ikke skjuler kostnader på et annet.','methodBoundary':'At en fysikkmodell bruker reelle tall viser at matematikk er metodisk integrert, men etablerer ikke alene platonisme. Omvendt viser en formell nominalisering ikke at den er explanatorisk eller praktisk likeverdig. Begge overgangene trenger egne argumenter.','case':'Et case kan være en fysikkmodell der kontinuerlige størrelser er avgjørende i den standard matematiske formuleringen. Analysen kan undersøke hva vitenskapens empiriske suksess faktisk bekrefter: den fysiske strukturen, matematisk formalisme, abstrakte objekter eller en kombinasjon.','caseTest':'Caset bør teste om en nominalistisk reformulering bevarer prediksjoner og forklaring, og om platonisten kan forklare hvorfor matematikkens rolle gir ontologisk snarere enn bare instrumentell støtte. Da blir uunnværlighetsargumentet en konkret inferens, ikke et slagord.','sourceNote':'Philosophy of Mathematics gir feltkartet, Platonism in Mathematics presiserer den realistiske ontologien og dens argumenter, og Nominalism in Mathematics dekker eliminative og fiksjonalistiske alternativer.','empiricalBoundary':'Filosofikildene dokumenterer ikke at en bestemt matematisk modell faktisk er uerstattelig i en konkret vitenskap. Det må begrunnes gjennom fagspesifikk metode- og modellhistorie dersom caset skal bære et uunnværlighetspremiss.','limit':'Artikkelen dekker ikke alle varianter av strukturalisme eller fiksjonalisme. Den etablerer den sentrale ontologi–epistemologi-konflikten som gjør slike mellomposisjoner forståelige og evaluerbare.','mastery':'Leseren skal kunne rekonstruere uunnværlighetsargumentet, forklare Fields nominalistiske svar og vise hvorfor matematikks objektivitet og epistemiske tilgang er to forskjellige problemer.'}),
article({id:'em_filosofi_matematisk_bevis_formalisme_intuisjonisme',title:'Matematisk bevis: logicisme, formalisme og intuisjonisme',level:3,definition:'Rivaliserende grunnlagsprogrammer for hva matematisk sannhet og bevis består i, og hvilke slutningsprinsipper som er legitime.',concepts:[concept('logicisme','Logicisme','Programmet som forsøker å vise at matematikk, særlig aritmetikk, kan reduseres til eller utledes fra logikk sammen med passende definisjoner.','Logicisme må skilles fra den svakere påstanden at matematikk bruker logikk; Frege og Russell ønsket et langt sterkere fundamentalt reduksjonsforhold.','Begrepet gjør det mulig å spørre hvilke aksiomer og definisjoner som faktisk er logiske, og hva paradokser og senere resultater betyr for reduksjonsambisjonen.'),concept('matematisk_formalisme','Matematisk formalisme','Teorier som legger avgjørende vekt på formelle symbolsystemer, syntaktiske regler og konsistens fremfor en platonistisk ontologi av matematiske objekter.','Formalisme må skilles mellom enkel «spillformalisme» og Hilberts mer sofistikerte program, der finitt innhold og metamatematisk konsistens spiller bestemte roller.','Begrepet gjør Gödels begrensninger relevante uten å feilaktig konkludere at enhver bruk av formelle systemer er filosofisk tilbakevist.'),concept('matematisk_intuisjonisme','Matematisk intuisjonisme','Brouwers grunnlagsposisjon der matematikk forstås som konstruktiv mental aktivitet og sannhet knyttes til muligheten for konstruksjon eller bevis.','Intuisjonisme må skilles fra vanlig intuisjon eller gjetning; posisjonen medfører systematiske logiske endringer, blant annet avvisning av generell bruk av loven om det utelukkede tredje.','Begrepet viser hvordan en teori om matematisk eksistens kan endre hvilke bevisformer som aksepteres, ikke bare hvordan de filosofisk beskrives.')],methods:['met_filosofi_deduktiv_analyse','met_filosofi_kildekritisk_verklesning'],hook:'fil_matematikkfilosofi_02',thinkers:[T.frege,T.russell,T.hilbert,T.brouwer,T.godel].slice(0,4),sources:['sep-philosophy-mathematics','sep-formalism-mathematics','sep-intuitionism'],anchors:['logicisme','Hilbert','Brouwer','intuisjonisme'],debate:'Frege og Russell søker et logicistisk fundament, Hilbert forsvarer et formalistisk program for sikkerhet gjennom metamatematikk, og Brouwer gjør konstruksjon og intuisjonistisk logikk grunnleggende; Gödel-resultater endrer særlig hva bestemte formalistiske og reduksjonistiske programmer kan love.',problem:'Et matematisk bevis synes å gi en type nødvendighet som empiriske undersøkelser ikke gir. Men hva gjør beviset legitimt: logiske regler, formell derivabilitet i et aksiomsystem eller en konstruksjon som faktisk kan gjennomføres? Grunnlagsteoriene gir forskjellige svar og kan derfor være uenige om samme bevisform.',stakes:'Spørsmålet får konkrete følger når klassisk matematikk bruker eksistensbevis som ikke konstruerer objektet, eller når et formelt system kan uttrykke sanne aritmetiske påstander det ikke selv kan bevise. Da er filosofi om bevis ikke et pyntelag over matematikk, men en analyse av legitime inferens- og sannhetskrav.',contrast:'Logicismen vil redusere matematikk til logikk; Hilberts program vil sikre ideal matematikk gjennom finitt metamatematikk og konsistens; Brouwers intuisjonisme avviser at klassiske sannhetsprinsipper alltid er legitime uten konstruksjon. Gödel endrer mulighetsrommet for formell fullstendighet.',argument:['P1: Frege og Russell forsøker å grunnlegge aritmetikken gjennom logiske prinsipper og definisjoner. Hvis reduksjonen lykkes, forklares matematisk nødvendighet gjennom logisk nødvendighet, men prosjektet må vise at de nødvendige aksiomene og konstruksjonene faktisk har den logiske statusen det hevdes.','P2: Hilberts program flytter spørsmålet til formelle systemer og finitt metamatematikk: idealiserte infinitære metoder kan forsvares dersom deres konsistens og konservativitet over et sikkert finitt grunnlag kan etableres. Det er et mer sofistikert prosjekt enn påstanden at matematikk bare er et meningsløst symbolspill.','P3: Brouwer avviser at klassisk logikk uten videre bestemmer matematisk sannhet. Et eksistensutsagn krever konstruksjon, og loven om det utelukkede tredje kan ikke brukes generelt for uavgjorte matematiske utsagn. Intuisjonismen endrer dermed selve kriteriet for akseptabelt bevis.','K: Gödel viser at tilstrekkelig sterke konsistente formelle systemer har interne begrensninger, men resultatet velger ikke automatisk intuisjonisme eller platonisme. Det viser at grunnlagsprogrammer må formuleres med presisjon: logicisme, formalisme og intuisjonisme er rivaler om hva matematisk sannhet og bevis krever, ikke bare om notasjon.'],objection:'Innvending: Moderne matematikere kan arbeide effektivt uten å velge mellom disse filosofiene. Det kan tyde på at grunnlagsstriden ikke påvirker «ekte matematikk» og derfor er mest historisk.','reply':'Svar: Hverdagspraksis kan være stabil på tvers av filosofiske tolkninger, men grenseområder gjør forskjellen synlig: konstruktiv matematikk, bevisassistenter, setningsteori og spørsmål om uavhengighet tvinger frem eksplisitte valg av logikk, aksiomer og beviskriterier.','stress':'Gödels ufullstendighet er særlig utsatt for overtolkning. At et formelt system ikke kan bevise alle aritmetiske sannheter under bestemte betingelser innebærer ikke at «menneskesinnet er uformelt» eller at platonisme er bevist. Filosofisk bruk krever at teoremets formelle forutsetninger bevares.',theoryNotes:['Frege og Russell representerer logicismens ambisjon om å redusere aritmetikk til logikk, selv om deres konkrete prosjekter og tekniske verktøy er forskjellige. Paradokser og spørsmål om aksiomenes status viser hvorfor reduksjonen er filosofisk omstridt.','Hilbert søker sikkerhet gjennom formalisering og metamatematikk, og hans program må forstås gjennom skillet mellom finitte og idealiserte metoder. Gödels andre ufullstendighetsteorem begrenser bestemte sterke konsistensbevis innenfor programmet.','Brouwer gjør matematisk aktivitet og konstruksjon grunnleggende og godtar derfor ikke alle klassiske eksistensbevis. Intuisjonistisk logikk er en konsekvens av et annet sannhets- og bevisbegrep, ikke en tilfeldig teknisk restriksjon.'],methodNote:'Ta et konkret klassisk eksistensbevis og marker hvilke trinn som bruker tertium non datur, ikke-konstruktiv reductio eller infinitære antakelser. Sammenlign deretter hva logicist, formalist og intuisjonist mener trinnene etablerer.','methodBoundary':'Formell korrekthet innen et valgt system og filosofisk begrunnelse av systemet er to nivåer. Et bevis kan være syntaktisk gyldig relativt til aksiomer samtidig som grunnlagsdebatten spør hvorfor disse aksiomene eller logikkreglene bør aksepteres.','case':'Et dokumentert case kan være et bevis i en moderne proof assistant der logisk grunnlag og konstruktivitetsvalg er eksplisitte. Dette gjør det mulig å se hvilke slutningsregler som faktisk brukes uten å anta at programvaren i seg selv avgjør den filosofiske grunnlagsstriden.','caseTest':'Caset bør sammenligne hva som endres dersom klassisk valg eller tertium non datur fjernes. Dersom et teorem fortsatt kan konstrueres, er forskjellen liten i dette tilfellet; dersom beviset bryter sammen, får grunnlagsposisjonene en konkret analytisk forskjell.','sourceNote':'Philosophy of Mathematics brukes til feltets grunnlagsprogrammer, Formalism in Mathematics til Hilbert og formalistiske varianter, og Intuitionism til Brouwers konstruktive posisjon og dens logiske konsekvenser.','empiricalBoundary':'Påstander om hva et bestemt formelt system eller proof assistant faktisk tillater må dokumenteres fra den tekniske spesifikasjonen. Filosofikildene forklarer hvorfor slike valg er grunnlagsmessig betydningsfulle, ikke implementasjonsdetaljene.','limit':'Artikkelen gir ikke en full teknisk innføring i Gödels teoremer eller moderne bevisteori. Den etablerer den filosofiske arkitekturen som trengs for å bruke slike resultater uten å gjøre dem til løse metaforer.','mastery':'Leseren skal kunne skille logicisme, Hilbert-formalisme og Brouwer-intuisjonisme, forklare hvorfor intuisjonisme endrer bevispraksis og formulere en nøktern konsekvens av ufullstendighet uten overdrivelse.'})]}),

area({id:'handlingsfilosofi',area_id:'filosofi_handlingsfilosofi',title:'Handlingsfilosofi, intensjon og agency',tagline:'Hva som gjør en hendelse til en handling, hvordan intensjoner virker og hvordan vi handler sammen.',method:{id:'met_filosofi_handlingsforklaring',title:'Handlingsforklaring',description:'Rekonstruerer forholdet mellom intensjon, grunner, årsaker, planstruktur og observerbar handling uten å blande normativ og kausal forklaring.',data_forms:['handlingskjede','grunn–årsak-matrise','plananalyse']},places:['universitet','arbeidssted','offentlig institusjon','organisasjon'],articles:[
article({id:'em_filosofi_intensjon_grunner_arsaker_handling',title:'Intensjon, grunner og årsaker i handling',level:2,definition:'Hva som skiller intensjonale handlinger fra hendelser, og om grunner forklarer handling ved også å være årsaker.',concepts:[concept('handlingsintensjon','Handlingsintensjon','En fremtids- eller handlingsrettet holdning som organiserer hva en agent skal gjøre og kan strukturere planlegging, oppmerksomhet og utførelse.','Intensjon må skilles fra ønske og prediksjon: å tro at jeg kommer til å gjøre noe er ikke nødvendigvis å ha bestemt eller planlagt å gjøre det.','Begrepet gjør Anscombes praktiske kunnskap, Davidsons kausalisme og Bratmans planorienterte teori sammenlignbare.'),concept('motiverende_grunn','Motiverende grunn','Den grunnen agenten faktisk handler på eller som inngår i forklaringen av hvorfor agenten handlet, uavhengig av om grunnen normativt var god.','Motiverende grunner må skilles fra normative grunner som taler for en handling. En feilaktig tro kan motivere uten å gi objektivt god begrunnelse.','Begrepet hindrer handlingsforklaring i å bli blandet med moralsk eller rasjonell godkjenning av handlingen.'),concept('handlingsarsak','Handlingsårsak','En årsaksfaktor som inngår i produksjonen av en handling, der en sentral strid er om relevante grunner og intensjoner kan være slike årsaker.','Handlingsårsak må skilles fra en ren kroppslig årsak som ikke gjør hendelsen til agentens handling; Davidson hevder at grunner kan være årsaker nettopp i en riktig rasjonaliserende forbindelse.','Begrepet bærer kausalismedebatten og gjør avvikende årsakskjeder til et presist moteksempelproblem.')],methods:['met_filosofi_argumentrekonstruksjon','met_filosofi_begrepsanalyse'],hook:'fil_handlingsfilosofi_01',thinkers:[T.anscombe,T.davidson,T.bratman,T.hume],sources:['sep-action','sep-intention','sep-reasons-action'],anchors:['Anscombe','Davidson','intensjon','grunner'],debate:'Anscombe analyserer intensjonal handling gjennom praktisk kunnskap og spørsmålet «Hvorfor?», Davidson hevder at rasjonaliserende grunner også kan være årsaker, og Bratman forklarer intensjon som planstruktur; rivalene er uenige om hva som gjør en hendelse til agentens handling.',problem:'Når en person løfter armen frivillig og når armen løftes av en refleks, kan den observerbare bevegelsen være lik. Handlingsfilosofien søker det som gjør den første hendelsen til en intensjonal handling: intensjon, praktisk kunnskap, grunner, kausal historie eller en kombinasjon.',stakes:'Forklaringen må håndtere feil, uvitenhet og avvikende kausalitet. Dersom en grunn bare er en etterrasjonalisering, forklarer den ikke handlingen; dersom enhver mental årsak er nok, kan en nervøs tro forårsake nettopp den hendelsen agenten ønsket uten at den derfor ble gjort med hensikt.',contrast:'Anscombe starter fra agentens praktiske kunnskap og hvorfor-spørsmål, Davidson fra rasjonaliserende årsaksforklaring og Bratman fra intensjoner som stabile planer. De gir ulike bilder av agentens forhold til egen handling.',argument:['P1: Anscombe hevder at intensjonal handling kjennetegnes ved at et bestemt «Hvorfor?»-spørsmål har anvendelse og at agenten normalt kjenner hva hun gjør på en praktisk, ikke-observasjonell måte. Dette flytter forklaringen fra ren kroppsbevegelse til handlingens plass i agentens begrunnede aktivitet.','P2: Davidson argumenterer for at en primær grunn – typisk en pro-holdning sammen med en relevant tro – kan rasjonalisere handlingen og samtidig være dens årsak. Dermed trenger vi ikke velge mellom «handling forklart av grunner» og «handling forklart kausalt», så lenge kausalforbindelsen er av riktig type.','P3: Avvikende årsakskjeder utfordrer en enkel kausalisme: en agents intensjon kan forårsake den ønskede hendelsen gjennom nervøsitet eller tilfeldige mellomledd uten at hendelsen utføres med den tilsiktede kontrollen. Bratmans planperspektiv tilfører tidslig stabilitet og koordinering som en enkelt mental årsak ikke fanger.','K: Intensjonal handling kan derfor ikke identifiseres med bevegelse pluss et samtidig ønske. En god teori må forklare praktisk kunnskap, rasjonaliserende grunner, korrekt kausal kontroll og intensjonens planfunksjon; Anscombe, Davidson og Bratman er reelle rivaler om hvordan disse elementene henger sammen.'],objection:'Innvending: Kausalismen kan synes å gjøre handling for passiv: hvis mentale tilstander «forårsaker» kroppen på samme måte som andre hendelser, forsvinner agenten som opphav. Ikke-kausale teorier hevder derfor at agency krever en annen type forklaring enn hendelseskausalitet.','reply':'Svar: Davidson trenger ikke behandle agenten som et rent sted der årsaker kolliderer; grunnen er agentens egen holdning og tro. Likevel gjenstår spørsmålet om årsaksmodellen forklarer kontroll og eierskap. Agent-kausale eller ikke-kausale teorier må på sin side forklare hvordan grunner kobles til fysisk utførelse uten forklaringsgap.','stress':'En annen stresstest er svak vilje. En person kan dømme at A er best, men med vilje gjøre B. Handlingsfilosofien må kunne skille intensjon, vurdering og motivasjon slik at akrasia er mulig uten at all handling blir irrasjonell støy.',theoryNotes:['Anscombes Intention er grunnleggende fordi hun analyserer intensjonal handling gjennom praktisk kunnskap, beskrivelse og hvorfor-spørsmål, ikke bare som et psykologisk forstadium før bevegelsen.','Davidsons Actions, Reasons, and Causes etablerer den moderne kausalismens kjerne: grunner kan rasjonalisere og kausalt forklare samme handling. Avvikende årsakskjeder viser samtidig at «årsaket av riktig grunn» trenger ytterligere presisering.','Bratmans Intention, Plans, and Practical Reason analyserer intensjoner som del av planer som stabiliserer beslutninger over tid og koordinerer fremtidige handlinger. Det gir intensjon en funksjon som verken enkelt ønske eller prediksjon har.'],methodNote:'Rekonstruer en handlingskjede med agentens tro, mål, intensjon, mellomhandlinger og resultat. Marker separat hvilke grunner som faktisk motiverte, hvilke som normativt talte for handlingen, og hvilke hendelser som var kausalt nødvendige.','methodBoundary':'Intervjuer og dokumenter kan gi evidens for hva en agent oppga som grunn, men de garanterer ikke motivets sannhet. Filosofisk handlingsanalyse må derfor skille første-persons begrunnelse, observerbar atferd og kausal hypotese.','case':'Et case kan være en dokumentert beslutningsprosess der en aktør utarbeider en plan, endrer den etter ny informasjon og til slutt handler. Materialet gjør det mulig å se hvordan intensjon stabiliserer og reviderer handling over tid i stedet for å gjette ut fra sluttresultatet.','caseTest':'Sammenlign et tilfelle der resultatet oppstår gjennom planen med et tilfelle der samme resultat skjer tilfeldig. Hvis teorien ikke kan skille dem, fanger den ikke kontroll. Deretter spør man om agentens oppgitte grunn også var en normativt god grunn eller bare en motivasjon.','sourceNote':'Action gir feltets kausale og ikke-kausale hovedlinjer, Intention dekker Anscombe, Davidson og Bratman, og Reasons for Action presiserer skillet mellom motiverende, forklarende og normative grunner.','empiricalBoundary':'Filosofikildene kan ikke fastslå hva en bestemt historisk aktør faktisk hadde i hodet. Slike påstander krever brev, intervjuer, protokoller eller annen dokumentasjon; filosofien organiserer hvilke slutninger materialet kan bære.','limit':'Artikkelen gir ikke en full teori om fri vilje, som allerede behandles i sinnsfilosofien. Den avgrenser den mer grunnleggende analysen av handling, intensjon og grunner som fri-vilje-debatten forutsetter.','mastery':'Leseren skal kunne forklare Anscombes hvorfor-spørsmål, rekonstruere Davidsons grunner-som-årsaker og bruke avvikende kausalitet til å teste om en teori faktisk forklarer kontroll.'}),
article({id:'em_filosofi_delt_handling_kollektiv_agency_ansvar',title:'Delt handling, kollektiv agency og ansvar',level:3,definition:'Hva som gjør at flere personer handler sammen som et «vi», og når grupper eller medlemmer kan være bærere av intensjon og ansvar.',concepts:[concept('delt_intensjon','Delt intensjon','En struktur av intensjoner og gjensidig avhengighet som gjør at flere agenter ikke bare handler parallelt, men retter seg mot en felles aktivitet som sådan.','Delt intensjon må skilles fra at flere tilfeldigvis ønsker samme resultat. To personer som løper mot samme tak i regnet handler parallelt; et lag som utfører en avtalt bevegelse handler sammen.','Begrepet gjør Bratmans reduktive planmodell og Searles mer grunnleggende vi-intensjonalitet direkte sammenlignbare.'),concept('kollektiv_agency','Kollektiv agency','Evnen en gruppe kan ha til å danne, opprettholde og utføre mål eller beslutninger på en måte som gjør gruppe-nivået forklaringsmessig relevant.','Kollektiv agency må skilles fra metaforen at enhver organisasjon er én person. Spørsmålet er hvilke strukturer av beslutning, representasjon og kontroll som eventuelt gjør gruppeagens mer enn summen av enkeltbidrag.','Begrepet bærer debatten mellom individualistiske reduksjoner og teorier om gruppeagenter hos blant andre Gilbert og Pettit.'),concept('kollektivt_ansvar','Kollektivt ansvar','Ansvar som tilskrives en gruppe, organisasjon eller et fellesskap for handlinger eller unnlatelser som ikke enkelt kan reduseres til én persons isolerte bidrag.','Kollektivt ansvar må skilles fra automatisk skyld ved medlemskap. En ansvarsteori må forklare beslutningsstruktur, deltakelse, kunnskap, kontroll og hvordan gruppeansvar relateres til individuelle ansvar.','Begrepet gjør etiske konsekvenser av kollektiv agency analyserbare uten å hoppe fra «gruppen gjorde det» til «alle medlemmer er like skyldige».')],methods:['met_filosofi_begrepsanalyse','met_filosofi_casebasert_etikk'],hook:'fil_handlingsfilosofi_02',thinkers:[T.bratman,T.searle,T.gilbert,T.pettit],sources:['sep-shared-agency','sep-collective-intentionality','sep-collective-responsibility'],anchors:['Bratman','Searle','delt intensjon','kollektiv agency'],debate:'Bratman forsøker å forklare delt agency gjennom strukturer av individuelle planer og gjensidige intensjoner, Searle postulerer en særskilt vi-intensjonalitet, og Gilbert og Pettit utvikler sterkere modeller for felles forpliktelse eller gruppeagency; ansvarsspørsmålet tester hvor mye ontologi teoriene trenger.',problem:'Mennesker gjør ting sammen som ingen av dem gjør alene: spiller kvartett, vedtar politikk, driver selskaper og organiserer protester. En ren liste over individuelle bevegelser kan være den samme i et tilfeldig sammenfall og i koordinert samarbeid. Handlingsfilosofien må forklare forskjellen.',stakes:'Forklaringen påvirker ansvar. Dersom en organisasjon kan være agent, kan det finnes gruppenivågrunner og forpliktelser. Dersom alt reduseres til individer, må teorien likevel forklare hvordan komplekse beslutningsprosedyrer skaper handlinger som ingen enkeltperson kontrollerer fullt ut.',contrast:'Bratman bruker sammenflettede individuelle intensjoner og planer, Searle fremhever irreduktibel vi-intensjonalitet, Gilbert felles forpliktelse og Pettit gruppeagency gjennom rasjonell organisasjon. De deler fenomenet, men ikke ontologien.',argument:['P1: Bratman hevder at delt intensjon i en delt aktivitet kan analyseres gjennom individuelle intensjoner av typen «jeg har til hensikt at vi gjør J», gjensidig responsivitet og sammenpassende delplaner under felles kunnskap. Modellen forklarer koordinering uten å postulere et eget kollektivt sinn.','P2: Searle utfordrer en slik reduksjon ved å hevde at vi-intensjonalitet har en form som ikke kan konstrueres av et sett private jeg-intensjoner alene. Det avgjørende ved felles handling er at deltakerne representerer handlingen som vår aktivitet, ikke bare som et resultat flere individuelt ønsker.','P3: Gilbert og Pettit viser to måter å styrke kollektivnivået på. Gilbert analyserer felles forpliktelse som en normativ struktur mellom deltakere, mens Pettit kan behandle organiserte grupper som agenter når beslutningsprosesser gir konsistente holdninger og handlingskontroll på gruppenivå.','K: Kollektiv agency kan derfor ikke avgjøres ved å telle personer. Teoriene må forklare felles mål, gjensidig avhengighet, normativ binding og beslutningsstruktur, og deretter vise om disse trekkene kan reduseres til individuelle holdninger eller krever et genuint gruppe-nivå.'],objection:'Innvending: Sterke teorier om gruppeagency risikerer å reifisere organisasjoner og skjule hvem som faktisk hadde makt. Å si «selskapet bestemte» kan gjøre konkrete ledere, ansatte eller eiere mindre synlige i ansvarsvurderingen.','reply':'Svar: Gruppeagency bør ikke erstatte individanalyse. En god teori må tillate flernivåansvar: institusjonens beslutningsstruktur kan være explanatorisk relevant samtidig som enkeltpersoners kunnskap, kontroll og bidrag undersøkes. Gruppeansvar fritar ikke automatisk medlemmer og medlemsskyld følger ikke automatisk av gruppen.','stress':'Motsatt kan ren individualisme miste emergente trekk. En komité kan fatte et flertallsvedtak ingen enkeltmedlem støtter som sitt førstevalg, og en organisasjons politikk kan vedvare gjennom utskifting av personer. Da må individualisten forklare stabiliteten uten å bare gjenta medlemslisten.',theoryNotes:['Bratmans Shared Agency viderefører plan-teorien til sosial handling og søker en ontologisk konservativ analyse: delt aktivitet bygges av individuelle intensjoner, subplaner og felles kunnskap.','Searle bruker eksempler der identiske bevegelser kan være tilfeldige eller kollektive og gjør vi-intensjonalitet til forskjellen. Dette presser Bratman-lignende teorier på om individnivået virkelig fanger aktivitetens «vi»-form.','Gilbert analyserer joint commitment som normativt bindende, mens Pettit undersøker hvordan grupper kan tilfredsstille rasjonalitets- og kontrollbetingelser for agency. De viser at kollektivitet både er et intensjonalt og institusjonelt spørsmål.'],methodNote:'Kartlegg først beslutningsstrukturen: hvem kunne foreslå, vetoere, stemme og utføre. Deretter kartlegges deltakeres intensjoner og gjensidige forventninger. Bare hvis begge nivåer er synlige, kan man vurdere om «gruppen handlet» er en forklarende påstand.','methodBoundary':'Organisasjonskart og protokoller viser formelle roller, men ikke alltid faktiske intensjoner eller uformell makt. Filosofisk kollektiv agency må derfor kobles til dokumenterte beslutningsspor og må ikke brukes som snarvei til ansvar.','case':'Et egnet case er en komitébeslutning med publisert mandat, stemmeprotokoll og gjennomføring. Man kan sammenligne komiteens vedtak med enkeltmedlemmenes preferanser og spørre om gruppe-nivået har en stabil holdning som forklarer videre handling.','caseTest':'Caset bør også undersøke et ansvarsspørsmål når utfallet blir skadelig. Er komiteen ansvarlig, bare flertallet, lederen, administrasjonen som utførte vedtaket eller flere nivåer samtidig? Teoriene må begrunne forskjellen gjennom kontroll og forpliktelse.','sourceNote':'Shared Agency gir Bratman og konkurrerende analyser, Collective Intentionality utvider feltet til vi-holdninger og sosial ontologi, og Collective Responsibility tester hvilke normative konsekvenser gruppeagens kan ha.','empiricalBoundary':'Filosofikildene avgjør ikke hvordan en bestemt organisasjon faktisk tok en beslutning. Det krever vedtekter, protokoller, intervjuer eller arkiv. Filosofien gir kriterier for når slike fakta støtter en påstand om kollektiv handling.','limit':'Artikkelen gir ikke en generell selskaps- eller organisasjonsteori. Den avgrenser agency- og ansvarsspørsmålene slik at institusjonelle caser kan analyseres uten antropomorfisme eller metodologisk individualisme som ubegrunnet forhåndsvalg.','mastery':'Leseren skal kunne skille parallell aktivitet fra delt handling, rekonstruere Bratman–Searle-konflikten og vise hvorfor gruppeansvar og individuelt ansvar må analyseres på relaterte, men ikke identiske nivåer.'})]}),

area({id:'fysikkfilosofi',area_id:'filosofi_fysikkfilosofi',title:'Fysikkfilosofi, romtid og kvanteteori',tagline:'Hvordan moderne fysikk utfordrer metafysiske begreper om tid, lokalitet, realisme og måling.',method:{id:'met_filosofi_fysikkfortolkning',title:'Fysikkfilosofisk fortolkningsanalyse',description:'Skiller den matematiske fysikkteorien, empiriske resultater og metafysiske fortolkninger og tester hvilke konklusjoner data faktisk underbestemmer.',data_forms:['teori–fortolkning-matrise','tankeeksperiment','antakelseskart']},places:['universitet','forskningsinstitusjon','vitenskapsmuseum','observatorium'],articles:[
article({id:'em_filosofi_romtid_relativitet_tid',title:'Romtid, relativitet og tidens ontologi',level:3,definition:'Hvordan spesial- og generell relativitet påvirker begreper om samtidighet, romtid og hva som eksisterer over tid.',concepts:[concept('romtid','Romtid','Den firedimensjonale geometriske strukturen som i relativistisk fysikk organiserer hendelser gjennom romlige og temporale relasjoner i én samlet beskrivelse.','Romtid må skilles fra forestillingen om et fysisk stoff som nødvendigvis eksisterer på samme måte som materie; substantivalisme og relasjonalisme gir ulike ontologiske tolkninger av geometrien.','Begrepet gjør Minkowskis geometrisering og filosofiske spørsmål om hva teorien forplikter oss til, analytisk separate.'),concept('relativitet_av_samtidighet','Relativitet av samtidighet','Resultatet i spesialrelativitet at romlig separerte hendelsers samtidighet avhenger av valg av inertialsystem, uten en privilegert absolutt samtidighetsrelasjon i teorien.','Relativitet av samtidighet må skilles fra subjektiv tidsopplevelse og fra den trivielle påstanden at klokker kan vise feil; den følger av teoriens struktur og lys-signaler mellom referansesystemer.','Begrepet er sentralt i argumenter om presentisme og eternalismelignende tidsontologier fordi et globalt «nå» blir vanskelig å gjøre fysisk privilegert.'),concept('relativistisk_tidsontologi','Relativistisk tidsontologi','Metafysiske teorier om hva som eksisterer og hvordan temporal tilblivelse skal forstås når samtidighet og romtid beskrives relativistisk.','Tidsontologi må skilles fra fysikkens empiriske ligninger: teorien kan begrense metafysiske muligheter uten at én ontologi følger logisk av formalismen alene.','Begrepet gjør Putnam-lignende argumenter for fire-dimensjonal realisme og forsøk på relativistisk kompatible becoming-teorier til reelle rivaler.')],methods:['met_filosofi_begrepsanalyse','met_filosofi_tankeeksperiment'],hook:'fil_fysikkfilosofi_01',thinkers:[T.einstein,T.minkowski,T.reichenbach,T.putnam],sources:['sep-spacetime-bebecome','sep-spacetime-theories','sep-time'],anchors:['Einstein','Minkowski','samtidighet','romtid'],debate:'Einsteins relativitet og Minkowskis romtidsgeometri utfordrer et absolutt simultant «nå», mens Reichenbach og Putnam viser ulike filosofiske konsekvenser for geometri og tidsontologi; striden gjelder hva fysikkens struktur faktisk forplikter metafysikken til.',problem:'Før relativitet er det lett å forestille seg at verden har ett universelt nå som deler alle hendelser i fortid, nåtid og fremtid. Spesialrelativitet gjør samtidighet mellom fjerne hendelser avhengig av inertialsystem. Da må tidsfilosofien forklare om et metafysisk privilegert nå kan bevares og til hvilken pris.',stakes:'Det er fristende å si at «Einstein beviste at tiden er en illusjon» eller at «alt eksisterer samtidig». Begge er for grove. Relativitet gir presise fysiske relasjoner; overgangen til presentisme, eternalismelignende blokk-univers eller becoming-teori er en filosofisk fortolkning med ekstra premisser.',contrast:'Einstein etablerer relativitetsprinsipp og lyshastighetsstruktur, Minkowski gir den geometriske romtidsformen, Reichenbach analyserer geometri og konvensjon, og Putnam bruker relativitetsstrukturen i et metafysisk argument om realitet på tvers av tid.',argument:['P1: I spesialrelativitet finnes det ikke én rammeuavhengig samtidighetsrelasjon for romlig separerte hendelser. To observatører i relativ bevegelse kan være uenige om hvilke fjerne hendelser som er samtidige uten at noen må ha en defekt klokke eller mangle informasjon.','P2: Minkowskis romtidsgeometri gjør denne strukturen naturlig ved å representere hendelser i en fire-dimensjonal manifold med invariant intervallstruktur. Den geometriske representasjonen er mer enn en illustrasjon, men spørsmålet om den også innebærer at alle tidspunkter «eksisterer likt» er et videre ontologisk trinn.','P3: Putnam-lignende argumenter hevder at relativitetsprinsipp og realitetens transitive struktur undergraver et absolutt privilegert nå. Presentisten kan svare ved å innføre ekstra struktur, lokale becoming-begreper eller alternative metafysiske modeller, men må forklare hvorfor denne strukturen ikke vises i fysikken.','K: Relativitet legger derfor sterke begrensninger på tidsontologi uten automatisk å gi én metafysisk fasit. Einstein og Minkowski leverer fysisk struktur; Reichenbach og Putnam viser hvordan filosofiske argumenter kan bygges på den, og rivalene må være tydelige om hvilke ekstra premisser de legger til.'],objection:'Innvending: Metafysikken trenger ikke avspeile alle symmetrier i fysikkens formalisme. Et absolutt nå kan eksistere selv om det er empirisk utilgjengelig, på samme måte som en teori kan ha skjult struktur som ikke er direkte målbar.','reply':'Svar: Muligheten er logisk åpen, men den får en forklaringskostnad. Dersom den ekstra strukturen aldri påvirker observasjon eller dynamikk, må presentisten forklare hvorfor vi bør tro på den og hvordan den forbedrer forklaringen fremfor å være en ontologisk rest av før-relativistisk intuisjon.','stress':'En annen innvending går motsatt vei: blokk-univers blir ofte fremstilt som om forandring forsvinner. Men eternalistiske modeller kan representere forskjellige egenskaper ved forskjellige tider. Konflikten gjelder hva som eksisterer og om det finnes objektiv becoming, ikke om objekter har ulik tilstand langs sin historie.',theoryNotes:['Einsteins 1905-artikkel om spesialrelativitet endrer samtidighetsbegrepet gjennom operative lys-signalprosedyrer og invarians, uten å skrive en ferdig metafysikk om tid. Det skillet må bevares.','Minkowskis Space and Time gir geometrien som samler rom og tid. Den er en nøkkel til hvorfor fire-dimensjonal beskrivelse er fysisk kraftfull, men filosofen må fortsatt argumentere for hva geometrien ontologisk betyr.','Reichenbach undersøker forholdet mellom geometri, måling og konvensjon, mens Putnam bruker relativitet til å argumentere mot en snever presentisme. De illustrerer hvordan samme fysikk kan inngå i forskjellige filosofiske prosjekter.'],methodNote:'Start med et enkelt Minkowski-diagram og marker hendelser, lyskjegler og samtidighetsflater for to inertialsystemer. Først etter at den fysiske strukturen er korrekt, legges metafysiske teser om eksistens og becoming inn som separate påstander.','methodBoundary':'Et tankeeksperiment må respektere relativitetens faktiske forutsetninger. Filosofisk analyse kan ikke endre den matematiske teorien for å redde en intuisjon, og fysikkens ligninger kan ikke uten broargument brukes som direkte bevis for en metafysisk etikett.','case':'Et museumscase kan være en utstilling med Einstein-toget eller tvillingparadokset. Dokumentasjonen gir en konkret representasjon av relativistisk tid som kan brukes til å skille målbar tidsdilatasjon fra den mer abstrakte striden om hvilke tider som eksisterer.','caseTest':'Caset bør spørre hva demonstrasjonen faktisk viser. Tidsdilatasjon er empirisk fysisk; «fortiden eksisterer nå» er ikke en måleavlesning. Leseren må kunne identifisere hvor den filosofiske broen legges og hvilke rivaler som avviser den.','sourceNote':'Being and Becoming in Modern Physics brukes til koblingen mellom relativitet og tidsontologi, Early Interpretations of General Relativity til geometriens filosofiske betydning, og Time til den bredere metafysiske begrepsrammen.','empiricalBoundary':'Tallfestede påstander om tidsdilatasjon, GPS-korrigering eller relativistiske eksperimenter må belegges med fysikkilder. SEP-kildene dokumenterer fortolkningsdebatten, ikke alle empiriske detaljer.','limit':'Artikkelen gir ikke en komplett innføring i generell relativitet eller alle tidsmetafysikker. Den etablerer det sentrale samtidighetsproblemet som gjør fysikkfilosofi til et selvstendig felt fremfor bare et underavsnitt om metafysikk.','mastery':'Leseren skal kunne forklare relativitet av samtidighet uten subjektivisme, bruke Minkowski-struktur korrekt og vise hvorfor en tidsontologisk konklusjon trenger et eksplisitt broargument.'}),
article({id:'em_filosofi_kvantemekanikk_maling_realisme',title:'Kvantemekanikk, måleproblem og realisme',level:3,definition:'Hvordan kvanteteoriens formalisme forbindes med bestemte måleresultater, og hvilke realistiske fortolkninger som kan forklare overgangen.',concepts:[concept('malingsproblem','Måleproblem','Problemet med å forklare hvordan en kvantetilstand som utvikler seg lineært og kan representere superposisjoner, forbindes med at målinger ser ut til å ha bestemte utfall.','Måleproblemet må skilles fra teknisk måleusikkerhet eller dårlig instrumentering; det oppstår fra forholdet mellom teoriens dynamikk, tilstandsbeskrivelse og bestemte observerte resultater.','Begrepet organiserer rivaliseringen mellom kollapsmodeller, Everett-fortolkninger og Bohm-lignende teorier.'),concept('kvantetilstand','Kvantetilstand','Den matematiske tilstandsrepresentasjonen, ofte uttrykt ved en bølgefunksjon eller tilstandsvektor, som brukes til å beregne sannsynligheter for mulige måleresultater.','Kvantetilstanden må skilles fra en ukritisk påstand om en fysisk bølge i vanlig tredimensjonalt rom; fortolkningene er nettopp uenige om hva tilstanden representerer ontologisk.','Begrepet gjør forskjellen mellom instrumentalisme, epistemiske fortolkninger og ontisk realisme eksplisitt.'),concept('kvantrealisme','Kvantrealisme','Familien av posisjoner som søker en realistisk fortolkning av kvanteteorien der teorien beskriver eller representerer fysisk virkelighet utover bare observerte utfall.','Kvantrealisme må skilles fra én bestemt fortolkning. Everett, Bohm og ulike kollapsteorier kan alle være realistiske samtidig som de postulerer svært forskjellig ontologi og dynamikk.','Begrepet åpner en sammenligning av hva hver fortolkning tar som grunnleggende og hvilke empiriske eller teoretiske kostnader den har.')],methods:['met_filosofi_abduktiv_vurdering','met_filosofi_tankeeksperiment'],hook:'fil_fysikkfilosofi_02',thinkers:[T.bohr,T.everett,T.bohm,T.bell],sources:['sep-qt-issues','sep-quantum-mechanics','sep-bell-theorem'],anchors:['måleproblem','Everett','Bohm','Bell'],debate:'Bohr-inspirerte pragmatiske eller komplementære fortolkninger, Everetts relative-state/mange-verdener-tilnærming og Bohms pilotbølgeteori gir forskjellige svar på måleproblemet, mens Bells teorem begrenser hvilke lokale skjulte-variabelbilder som kan bevare klassiske intuisjoner.',problem:'Kvantemekanikk gir ekstremt presise sannsynlighetsforutsigelser, men det er uklart hva formalismen sier finnes og hvorfor en måling gir ett bestemt resultat. Måleproblemet oppstår når lineær utvikling av superposisjoner ser ut til å fortsette inn i måleapparatet, mens erfaringen viser bestemte utfall.',stakes:'Fortolkningsdebatten kan ikke reduseres til at «observatøren skaper virkeligheten». Everett forsøker å beholde lineær dynamikk uten kollaps; Bohm legger til partikkelkonfigurasjon og guiding; kollapsmodeller endrer dynamikken. Hver løsning flytter kostnaden til et annet sted.',contrast:'Bohrs tekster understreker klassisk beskrivelse av eksperimentelle arrangementer og komplementaritet. Everett gjør alle grener i den universelle tilstanden dynamisk reelle. Bohm gir bestemte partikkelposisjoner og ikke-lokal guiding. Bell viser hvorfor lokal skjult variabel-teori møter sterke begrensninger.',argument:['P1: Standard kvanteformalisme lar en superposisjon utvikle seg lineært. Hvis et måleapparat selv behandles kvantemekanisk, ser den samlede tilstanden ut til å ende i en superposisjon av korrelerte apparat- og systemtilstander snarere enn ett unikt resultat. Det er kjernen i måleproblemet.','P2: Everett svarer ved å avvise fysisk kollaps: den universelle tilstanden utvikler seg lineært, og det vi kaller ulike utfall realiseres i decoherente grener eller relative tilstander. Løsningen bevarer dynamikken, men må forklare sannsynlighet og ontologien til grenstrukturen.','P3: Bohms teori bevarer bølgefunksjonen, men legger til faktiske konfigurasjoner som styres av den. Dermed finnes bestemte utfall, men teorien er eksplisitt ikke-lokal. Bells teorem viser hvorfor håpet om en enkel lokal skjult-variabelmodell som reproducerer kvantekorrelasjoner ikke kan opprettholdes under standard antakelser.','K: Måleproblemet viser derfor reell underbestemmelse mellom fortolkninger som kan dele mye empirisk innhold. Everett og Bohm er ikke bare metaforer; de endrer hva teorien sier finnes og hvordan bestemte utfall forklares. Bell innsnevrer mulighetsrommet, men velger ikke alene én full fortolkning.'],objection:'Innvending: Hvis rivaliserende fortolkninger gir samme observerbare prediksjoner, kan striden virke empirisk tom. En instrumentalist kan derfor hevde at fysikken bare trenger reglene for å beregne resultater, ikke en ytterligere ontologisk fortelling.','reply':'Svar: Instrumentalisme er selv en filosofisk posisjon om teoriens mål og representasjon. Fortolkningene påvirker hvordan vi forstår forklaring, sannsynlighet, ikke-lokalitet og hvilke teoriendringer som er meningsfulle. Dersom empirisk ekvivalens vedvarer, øker behovet for eksplisitte teoretiske sammenligningskriterier i stedet for at spørsmålet forsvinner.','stress':'Bell-resultatet er en særlig viktig kontroll mot populær overdrivelse. Teoremet viser ikke at «alt påvirker alt øyeblikkelig» uten forutsetninger; det viser at bestemte kombinasjoner av lokalitet og skjulte variabler ikke kan reproduksere kvanteprediksjonene. Fortolkningen av hvilke antakelser som bør oppgis er fortsatt filosofisk og fysisk omstridt.',theoryNotes:['Bohrs komplementaritetsprogram understreker betingelsene for meningsfulle eksperimentelle beskrivelser og advarer mot å tilskrive klassiske egenskaper uavhengig av målekontekst. Det er mer presist enn slagordet om at «bevissthet skaper resultatet».','Everetts Relative State Formulation beholder Schrödinger-dynamikken universelt. Filosofisk press flyttes til grenontologi, decoherence, identitet og hvorfor Born-sannsynligheter får normativ eller empirisk rolle i en teori uten unik kollaps.','Bohms skjulte-variabelteori gir bestemt konfigurasjon og klar måledynamikk, men aksepterer en ikke-lokal struktur. Bells arbeid viser hvorfor dette ikke bare er et tilfeldig særtrekk ved Bohm, men knyttet til dype begrensninger på lokale realistiske modeller.'],methodNote:'Bygg først en teori–fortolkning-matrise: hva beholder hver posisjon av standard dynamikk, hva legger den til eller endrer, hva er ontologien, og hvordan forklares bestemte utfall og sannsynlighet. Da kan styrker og kostnader sammenlignes på samme akser.','methodBoundary':'Tankeeksperimenter som Schrödingers katt og EPR må brukes med korrekt formell hensikt. De er ikke empiriske fotografier av «rare kvanteverdener», men verktøy for å presse bestemte teoriantakelser. Eksperimentelle Bell-resultater må dokumenteres fra fysikkilder hvis konkrete tall brukes.','case':'Et vitenskapsmuseum med dobbelspalte- eller Bell-demonstrasjon kan brukes som dokumentert case. Analysen bør først beskrive hva oppsettet faktisk måler, deretter identifisere hvilke fortolkningspåstander utstillingen legger til utover selve observasjonen.','caseTest':'Caset tester om utstillingen blander sannsynlighetsfordeling, «partikkel går begge veier» og bevisst observasjon som om de var samme påstand. Everett-, Bohm- og Bohr-inspirerte analyser kan vise hvordan samme data får forskjellige ontologiske fortolkninger.','sourceNote':'Philosophical Issues in Quantum Theory gir måleproblem og fortolkninger, Quantum Mechanics gir formell og konseptuell bakgrunn, og Bell’s Theorem avgrenser hva lokale skjulte-variabelmodeller kan gjøre.','empiricalBoundary':'SEP-kildene gir faglig fortolkningskontroll, men konkrete eksperimentresultater, feilmarginer og tekniske oppsett krever primærfysikk eller autoritative laboratoriekilder. Filosofien må ikke låne empirisk autoritet fra sin egen fortolkningslitteratur.','limit':'Artikkelen velger ikke én kvantefortolkning som endelig riktig og dekker ikke alle modeller. Den etablerer måleproblemet og Bell-begrensningen som minimumskunnskap før Everett, Bohm eller instrumentalisme kan sammenlignes seriøst.','mastery':'Leseren skal kunne formulere måleproblemet uten mystifisering, forklare hvordan Everett og Bohm løser forskjellige deler av det og angi nøkternt hva Bells teorem utelukker under hvilke antakelser.'})]}),

area({id:'sannsynlighet_beslutning',area_id:'filosofi_sannsynlighet_beslutning',title:'Sannsynlighet, risiko og beslutningsteori',tagline:'Hva sannsynlighet betyr, hvordan evidens bør endre tro og hva rasjonelt valg under usikkerhet krever.',method:{id:'met_filosofi_beslutningsteoretisk_analyse',title:'Beslutningsteoretisk analyse',description:'Formulerer utfall, sannsynligheter, preferanser og beslutningsregler eksplisitt og tester hvilke rasjonalitetsaksiomer som driver konklusjonen.',data_forms:['beslutningsmatrise','sannsynlighetsmodell','preferansekart']},places:['universitet','forskningsinstitusjon','forvaltningsorgan','risikoinstitusjon'],articles:[
article({id:'em_filosofi_sannsynlighet_frekvens_bayes',title:'Sannsynlighet: frekvens, grad av tro og Bayes',level:3,definition:'Rivaliserende fortolkninger av hva sannsynlighet er, og hvordan probabilistisk evidens kan kobles til rasjonell oppdatering.',concepts:[concept('frekventisme','Frekventisme','Fortolkninger der sannsynlighet forstås gjennom relative frekvenser eller grenser i gjentatte forsøk og dermed knyttes tett til repeterbare hendelsestyper.','Frekventisme må skilles fra den statistiske påstanden at observerte frekvenser er nyttige estimater; som fortolkning sier den noe sterkere om hva sannsynlighetsverdien betyr.','Begrepet gjør von Mises-lignende kollektivmodeller sammenlignbare med subjektivistiske og logiske sannsynlighetsfortolkninger.'),concept('subjektiv_sannsynlighet','Subjektiv sannsynlighet','Fortolkningen av sannsynlighet som grad av rasjonell eller koherent tro hos en agent, ofte strukturert av betting- eller representasjonsargumenter.','Subjektiv sannsynlighet må skilles fra tilfeldig personlig følelse; Ramsey og de Finetti pålegger grader av tro sterke koherenskrav og knytter dem til preferanse og beslutning.','Begrepet åpner for sannsynlighet på enkeltstående hendelser, men reiser spørsmålet om hvordan evidens og rasjonalitet begrenser subjektive priors.'),concept('bayesiansk_oppdatering','Bayesiansk oppdatering','Regelen eller normfamilien der grader av tro revideres i lys av evidens ved hjelp av betinget sannsynlighet og Bayes’ teorem.','Bayesiansk oppdatering må skilles fra Bayes’ teorem som matematisk identitet; den normative påstanden er at rasjonelle agenter under bestemte betingelser bør oppdatere på en bestemt måte.','Begrepet kobler sannsynlighetsfortolkning til bekreftelsesteori og gjør uenighet om priorer, likelihood og læringsregler eksplisitt.')],methods:['met_filosofi_abduktiv_vurdering','met_filosofi_premissproving'],hook:'fil_sannsynlighet_beslutning_01',thinkers:[T.mises,T.ramsey,T.definetti,T.carnap],sources:['sep-probability-interpret','sep-confirmation','sep-bayes-theorem'],anchors:['frekventisme','Ramsey','Bayes','subjektiv sannsynlighet'],debate:'Von Mises-lignende frekventisme knytter sannsynlighet til gjentatte frekvenser, Ramsey og de Finetti analyserer den som koherent grad av tro, og Carnap søker logiske bekreftelsesrelasjoner; Bayesianismen kobler fortolkning til en norm for evidensoppdatering.',problem:'«Det er 30 prosent sannsynlighet for regn i morgen» kan ikke uten videre forstås som at morgendagen gjentas uendelig mange ganger. Samtidig virker det for svakt å si at taleren bare føler seg 30 prosent sikker. Sannsynlighetsfilosofi spør hvilken type størrelse prosenttallet representerer.',stakes:'Fortolkningen påvirker hva det betyr å bekrefte en hypotese og hvordan enkeltstående risikoer bør beskrives. Frekvenser gir empirisk forankring, subjektive grader av tro håndterer unike hendelser, og logiske eller propensity-baserte teorier søker andre objektive forbindelser. Ingen løsning er gratis.',contrast:'Von Mises knytter sannsynlighet til kollektiv og frekvens, Ramsey og de Finetti til koherente credences og betting, Carnap til logiske bekreftelsesgrader. Bayes’ teorem kan brukes av flere, men teoriene er uenige om hva tallene betyr.',argument:['P1: Frekventisme forklarer sannsynlighet gjennom mønstre i gjentatte forsøk og unngår å gjøre en agents tro til målestokk for en fysisk sjanse. Problemet oppstår ved enkeltstående hendelser og ved å spesifisere den relevante referanseklassen eller den idealiserte uendelige sekvensen uten sirkularitet.','P2: Ramsey og de Finetti lar sannsynlighet uttrykke grader av tro som må være koherente med agentens preferanser og hypotetiske innsatser. Dette håndterer unike hendelser, men reiser spørsmålet om to koherente agenter med svært forskjellige priorer begge kan være like rasjonelle før evidens.','P3: Bayesiansk oppdatering gir en kraftig norm for hvordan evidens bør endre credence når likelihood og tidligere sannsynlighet er spesifisert. Men Bayes’ teorem alene bestemmer ikke prioren, og conditionalisation som læringsregel har egne forutsetninger. Matematisk identitet og epistemisk norm må derfor skilles.','K: Sannsynlighet har ikke én ukontroversiell filosofisk betydning. Frekventisme, subjektivisme og logiske tilnærminger forklarer ulike brukssituasjoner godt, mens Bayesianismen viser hvordan en fortolkning av grad av tro kan kobles til evidens. En analyse må angi hvilken sannsynlighetstype som brukes før tallet får epistemisk betydning.'],objection:'Innvending: I praksis kan statistikere bruke samme matematikk uten å ta stilling til sannsynlighetens metafysikk. Det kan tyde på at fortolkningsdebatten er uten konsekvens så lenge modellene predikerer godt.','reply':'Svar: Praktisk enighet om formelbruk skjuler normative forskjeller når evidens er svak, hendelser er unike eller beslutninger må tas. Hva en 0,01-verdi eller 90 prosent credence tillater oss å tro, og hvordan tidligere informasjon skal inngå, avhenger av fortolkning og inferensramme.','stress':'Bayesianismen får en egen stresstest gjennom problemet med priorer og «old evidence». Dersom nesten enhver prior kan gjøres koherent, trenger teorien ytterligere rasjonalitetskrav for å forklare hvorfor evidens bør trekke ulike agenter sammen og når en prior er urimelig.',theoryNotes:['Von Mises representerer en streng frekvensfortolkning som knytter sannsynlighet til kollektiver og langsiktige frekvenser. Styrken er objektiv empirisk orientering; vanskeligheten er enkeltstående sjanser og idealiseringen av relevante sekvenser.','Ramsey og de Finetti gjør grader av tro målbare gjennom beslutning og koherens. De er sentrale for subjektiv Bayesianisme, men deres program må skille konsistens fra mer substansielle krav om evidensrespons.','Carnap utvikler logiske sannsynlighets- og bekreftelsesideer der evidensrelasjonen søkes formaliseres. Sammen med Bayesianismen viser dette at «sannsynlighet» kan fungere som både fysisk, epistemisk og logisk begrep.'],methodNote:'Skriv først hva prosenttallet gjelder: en fysisk hendelsestype, en agentcredence eller en logisk støttegrad. Deretter dokumenteres prior, likelihood, data og oppdateringsregel. Uten dette kan samme tall skifte mening midt i argumentet.','methodBoundary':'En Bayes-beregning er bare så god som modell og input. Filosofisk analyse kan teste om oppdateringen er koherent og om fortolkningen passer problemet, men den kan ikke skape empirisk pålitelige sannsynligheter uten data og modellvalidering.','case':'Et case kan være en offentlig risikovurdering for en sjelden hendelse. Analysen kan spørre om prosenten er historisk frekvens, modellert fysisk sjanse eller ekspertens grad av tro, og hvordan ny evidens faktisk bør endre vurderingen.','caseTest':'Sammenlign to eksperter med samme likelihood, men ulike priors. Bayesianismen viser hvordan de oppdaterer, men det filosofiske spørsmålet er om priorforskjellen er rasjonelt tillatt og hvilke ytterligere data som kan gjøre dem konvergerende.','sourceNote':'Interpretations of Probability gir feltets hovedfortolkninger, Confirmation kobler sannsynlighet til evidens og vitenskapelig støtte, og Bayes’ Theorem skiller den matematiske identiteten fra normative og epistemiske anvendelser.','empiricalBoundary':'Risikonivå i et faktisk case må komme fra relevant statistikk eller modellrapport. SEP-kildene gir ingen lokalt estimat; de hjelper oss å tolke hva et estimat betyr og hvilke inferenser det kan støtte.','limit':'Artikkelen dekker ikke hele statistikkfilosofien eller alle objective-chance-teorier. Den etablerer den grunnleggende forskjellen mellom frekvens, grad av tro og oppdateringsnorm som senere statistiske debatter forutsetter.','mastery':'Leseren skal kunne forklare hvorfor Bayes’ teorem ikke i seg selv er en full epistemologi, skille frekventistisk og subjektiv sannsynlighet og identifisere hvor prior og likelihood kommer inn i en konkret inferens.'}),
article({id:'em_filosofi_beslutning_forventet_nytte_risiko',title:'Beslutningsteori: forventet nytte, risiko og usikkerhet',level:3,definition:'Hva rasjonelt valg under usikkerhet krever når alternativer har forskjellige utfall, sannsynligheter og verdier.',concepts:[concept('forventet_nytte','Forventet nytte','Den sannsynlighetsvektede nytten av mulige utfall for et handlingsalternativ, brukt i teorier der rasjonelt valg representeres som maksimering av forventet verdi.','Forventet nytte må skilles fra forventet pengeverdi; nytte kan representere preferanser og trenger ikke øke lineært med penger eller andre målbare goder.','Begrepet gjør von Neumann–Morgenstern og Savage-modeller sammenlignbare og viser hvilke aksiomer som må være oppfylt for representasjonen.'),concept('preferanseorden','Preferanseorden','En struktur som rangerer alternativer eller lotterier etter hva agenten foretrekker, ofte under krav som kompletthet, transitivitet og andre konsistensbetingelser.','Preferanseorden må skilles fra øyeblikkelig lyst; i normativ beslutningsteori brukes den som formalisert relasjon og kan vurderes for intern konsistens og respons på informasjon.','Begrepet viser hvordan representasjonsteoremer går fra kvalitative valgaxiomer til en kvantitativ nyttefunksjon.'),concept('usikkerhetsaversjon','Usikkerhetsaversjon','En systematisk preferanse for valg med bedre spesifisert sannsynlighet fremfor valg med tvetydig eller ukjent sannsynlighetsstruktur, selv når en enkel forventet-nytte-modell ville behandle dem likt.','Usikkerhetsaversjon må skilles fra vanlig risikoaversjon, som kan representeres gjennom nyttekurvatur når sannsynlighetene er kjente. Ellsberg-caser viser en annen reaksjon på ukjent sannsynlighet.','Begrepet utfordrer Savage-lignende aksiomer og viser hvorfor risiko og dyp usikkerhet ikke bør behandles som samme beslutningssituasjon.')],methods:['met_filosofi_normativ_sammenligning','met_filosofi_tankeeksperiment'],hook:'fil_sannsynlighet_beslutning_02',thinkers:[T.vonNeumann,T.morgenstern,T.savage,T.ellsberg],sources:['sep-decision-theory','sep-causal-decision','sep-risk'],anchors:['forventet nytte','Savage','Ellsberg','usikkerhet'],debate:'Von Neumann og Morgenstern viser hvordan konsistente preferanser over lotterier kan representeres ved forventet nytte, Savage kobler subjektiv sannsynlighet og valg under usikkerhet, og Ellsberg viser systematiske valg som utfordrer sentrale aksiomer; nyere kausal beslutningsteori åpner en annen konflikt om hva evidens skal styre.',problem:'Når et valg har flere mulige utfall, trenger rasjonalitet en regel for hvordan verdi og sannsynlighet kombineres. Forventet nytte gir en elegant modell, men paradokser og usikkerhet om selve sannsynlighetene viser at rasjonelt valg ikke alltid ser ut til å følge én enkel maksimumsregel.',stakes:'Beslutningsteori brukes i økonomi, medisin, forvaltning og AI, men filosofien må skille beskrivende treffsikkerhet fra normativ begrunnelse. At mennesker bryter et aksiom viser ikke automatisk at aksiomet er galt; at et teorem representerer konsistente preferanser viser ikke automatisk at preferansene er moralsk gode.',contrast:'Von Neumann–Morgenstern analyserer lotterier med kjente sannsynligheter, Savage utvikler valg under subjektiv usikkerhet, Ellsberg demonstrerer robust tvetydighetsaversjon, og kausal beslutningsteori utfordrer hvordan handling og evidens skal kobles i spesielle problemer.',argument:['P1: Von Neumann og Morgenstern viser at dersom preferanser over lotterier tilfredsstiller bestemte aksiomer, kan de representeres som maksimering av forventet nytte. Teoremet gir en sterk forbindelse mellom kvalitative rasjonalitetsbetingelser og en kvantitativ representasjon, men begrunnelsen hviler på aksiomene.','P2: Savage utvider prosjektet til situasjoner der sannsynlighetene ikke er objektivt oppgitt, ved å utlede både subjektive sannsynligheter og nytte fra preferanser over handlinger og tilstander. Særlig sure-thing-prinsippet spiller en sentral rolle i representasjonen.','P3: Ellsberg viser valg der mange foretrekker kjent risiko fremfor tvetydig sannsynlighet på måter som bryter Savage-lignende prinsipper. Hvis dette er rasjonelt tillatt, må en teori representere usikkerhetsaversjon eller flere sannsynlighetsmodeller i stedet for å avfeie mønsteret som inkonsistent.','K: Forventet nytte er derfor en kraftig normativ kandidat, ikke en definisjon av rasjonalitet. Beslutningsteorien må begrunne aksiomene, skille risiko fra tvetydighet og forklare om avvik skyldes kognitive feil eller legitime rasjonalitetsverdier som robusthet, føre-var-hensyn eller kausal kontroll.'],objection:'Innvending: Hvis enhver systematisk avvikstype fører til en ny beslutningsmodell, mister teorien normativ kraft. En enkel forventet-nytte-standard kan være nettopp det som trengs for å diagnostisere menneskelige bias i stedet for å rasjonalisere dem.','reply':'Svar: Normativ enkelhet er en verdi, men kan ikke frita axiomer fra begrunnelse. Ellsberg viser ikke bare støy; preferansene kan være stabile og sensitive for informasjonskvalitet. Spørsmålet er hvilke konsistenskrav som er rasjonelle når sannsynlighetsmodellen selv er usikker.','stress':'Newcomb-lignende problemer skaper en annen konflikt: evidensiell og kausal beslutningsteori kan anbefale forskjellige valg fordi de tolker korrelasjon mellom handling og utfall forskjellig. Dette viser at selv med nytte og sannsynlighet på plass gjenstår spørsmålet om hvilken type betingelse handlingen skal optimalisere.',theoryNotes:['Von Neumann og Morgensterns Theory of Games and Economic Behavior gir den klassiske forventet-nytte-representasjonen for risikable lotterier. Resultatet må leses som et teorem under aksiomer, ikke som en psykologisk lov om faktisk menneskelig valg.','Savages Foundations of Statistics integrerer subjektiv sannsynlighet og nytte gjennom preferanser og sure-thing-prinsippet. Modellen er filosofisk kraftig fordi sannsynlighet og verdi utledes sammen, men nettopp derfor blir axiombrudd teoretisk betydningsfulle.','Ellsbergs Risk, Ambiguity, and the Savage Axioms viser systematisk tvetydighetsaversjon. Casene har inspirert modeller med ikke-additive eller multiple sannsynligheter og en bredere diskusjon om rasjonell forsiktighet under dyp usikkerhet.'],methodNote:'Bygg en beslutningsmatrise med handlinger, tilstander, utfall, sannsynligheter og nytte. Marker deretter om sannsynlighetene er kjente, estimerte eller rent subjektive. Først da kan det avgjøres hvilken forventet-nytte-variant eller alternativ modell som faktisk testes.','methodBoundary':'En normativ beslutningsmodell kan vise intern konsistens, men kan ikke alene levere de empiriske sannsynlighetene eller moralske verdiene som mates inn. Føre-var- eller fordelingshensyn kan dessuten kreve normativ analyse utenfor individuell nytte.','case':'Et dokumentert case kan være en offentlig beslutning mellom et tiltak med kjent moderat kostnad og et alternativ med lavt estimert, men svært usikkert katastrofepotensial. Analysen kan skille forventet risiko fra tvetydighet om selve modellen.','caseTest':'Caset bør beregnes under minst to plausible sannsynlighetsmodeller og deretter analyseres med forventet nytte og en robust eller tvetydighetsavers modell. Uenigheten blir da synlig som teori om rasjonalitet, ikke som skjult justering av tallene.','sourceNote':'Decision Theory gir expected-utility- og Savage-rammene, Causal Decision Theory viser en rivalisering om hvordan handling bør kobles til sannsynlighet, og Risk gir begreper for risiko, usikkerhet og normative beslutningsproblemer.','empiricalBoundary':'Et beslutningscase krever egne kilder for sannsynligheter, kostnader og konsekvenser. SEP-kildene kan ikke legitimere et bestemt risikotall; de dokumenterer hvordan tallene bør inngå i argumentet og hvilke axiomer som gjør anbefalingen rasjonell.','limit':'Artikkelen dekker ikke spillteori, sosialt valg eller alle moderne ambiguity-modeller. Den etablerer expected-utility-kjernen og to sentrale presspunkter – tvetydighet og kausal/evidensiell konflikt – som gjør videre beslutningsteori forståelig.','mastery':'Leseren skal kunne forklare hva et representasjonsteorem faktisk viser, skille risikoaversjon fra usikkerhetsaversjon og bruke Ellsberg til å teste, ikke bare avvise, Savage-axiomene.'})]})
];

const NEW_DOMAIN_ORDER=['sprakfilosofi','religionsfilosofi','rettsfilosofi','matematikkfilosofi','handlingsfilosofi','fysikkfilosofi','sannsynlighet_beslutning'];
// This assertion intentionally catches an accidentally omitted area in the temporary materializer.
if(AREAS.length!==NEW_DOMAIN_ORDER.length) throw new Error(`Materializer area mismatch: ${AREAS.length} != ${NEW_DOMAIN_ORDER.length}. Ensure all seven area specs are present.`);

const existing={
  fagkart:readJson(P.fagkart), emner:readJson(P.emner), pensum:readJson(P.pensum), concepts:readJson(P.concepts),
  methods:readJson(P.methods), thinkers:readJson(P.thinkers), sources:readJson(P.sources), registry:readJson(P.registry)
};

const methodById=new Map(existing.methods.methods.map(x=>[x.method_id,x]));
const conceptById=new Map(existing.concepts.concepts.map(x=>[x.id,x]));
const thinkerById=new Map(existing.thinkers.thinkers.map(x=>[x.id,x]));
const sourceById=new Map(existing.sources.sources.map(x=>[x.id,x]));
const emneById=new Map(existing.emner.map(x=>[x.emne_id,x]));
const categoryById=new Map(existing.fagkart.categories.map(x=>[x.id,x]));
const moduleIds=new Set(existing.pensum.modules.map(x=>x.module_id));
const articleRegById=new Map(existing.registry.articles.map(x=>[x.id,x]));
const chapterRegById=new Map(existing.registry.chapters.map(x=>[x.id,x]));

for(const s of SOURCES){ if(!sourceById.has(s.id)){ existing.sources.sources.push(s); sourceById.set(s.id,s); } }

const methodQuality='Metoden skal brukes på et eksplisitt argument, begrep, tekst, formalisering, case eller dokumentert forhold; mellomleddet i analysen skal være synlig og etterprøvbart.';
for(const a of AREAS){
  if(methodById.has(a.method.id)) continue;
  const m={method_id:a.method.id,title:a.method.title,description:a.method.description,data_forms:a.method.data_forms,canonical_status:'canonical',quality_gate:methodQuality};
  existing.methods.methods.push(m);methodById.set(m.method_id,m);
}

const areaArticleIds=[];
for(const a of AREAS){
  for(const art of a.articles){
    areaArticleIds.push(art.id);
    if(emneById.has(art.id)||articleRegById.has(art.id)) throw new Error(`Already materialized article/emne ${art.id}`);
    for(const c of art.concepts){
      if(conceptById.has(c.id)) throw new Error(`New concept id collides with existing concept: ${c.id}`);
      const rel=art.concepts.filter(x=>x.id!==c.id).map(x=>x.id);
      const row={id:c.id,label:c.label,definition:c.definition,distinction:c.distinction,area_id:a.area_id,emne_ids:[art.id],level:art.level,related_ids:rel,common_confusions:[`å bruke ${c.label.toLocaleLowerCase('nb')} som løs etikett uten å vise hvilken inferens begrepet bærer`,`å blande ${c.label.toLocaleLowerCase('nb')} med et nærliggende, men analytisk forskjellig nivå`],quiz_guidance:'Spør etter definisjon, relevant distinksjon, argumentativ funksjon og anvendelse i et konkret problem; svaret må vise hvorfor begrepet endrer analysen.',status:'canonical'};
      existing.concepts.concepts.push(row);conceptById.set(c.id,row);
    }
  }
}

function ensureThinker(t,a,art){
  let row=thinkerById.get(t.id);
  const conceptIds=art.concepts.map(c=>c.id);
  if(!row){
    row={id:t.id,name:t.name,period:t.period,primary_area_id:a.area_id,status:'active',tier:t.tier||'core',why:`${t.name} er direkte relevant for ${a.title.toLocaleLowerCase('nb')} gjennom et navngitt verk og en argumentposisjon som materialiseres i det nye fagområdet.`,works:t.works,concept_ids:conceptIds.slice(0,3),topic_hook_ids:[art.hook],source_policy:'Verk og historiske påstander skal kontrolleres mot pålitelig utgave eller faglig sekundærkilde før synlig quiz- eller analysebruk.'};
    existing.thinkers.thinkers.push(row);thinkerById.set(t.id,row);
  } else {
    row.works=uniq([...(row.works||[]),...t.works]);
    row.concept_ids=uniq([...(row.concept_ids||[]),...conceptIds]).slice(0,12);
    row.topic_hook_ids=uniq([...(row.topic_hook_ids||[]),art.hook]);
  }
  return row;
}

const articlePath=(id)=>`data/fagverk/filosofi/articles/${id}.json`;
const chapterPath=(id)=>`data/fagverk/filosofi/chapters/filosofi-${id}.json`;
const proseSections=(a,art)=>{
  const thinkerNames=art.thinkers.map(t=>t.name);
  const sourceTitles=art.sources.map(id=>sourceById.get(id)?.title||id);
  const methodTitle=a.method.title;
  return [
    {id:'problem',title:'Problemet',paragraphs:[art.problem,art.stakes,art.contrast]},
    {id:'begreper',title:'Begrepene som bærer argumentet',paragraphs:art.concepts.map(c=>`${c.label} betegner ${c.definition.charAt(0).toLocaleLowerCase('nb')+c.definition.slice(1)} ${c.distinction} I denne artikkelen er funksjonen presis: ${c.role} Det betyr at begrepet må gjøre arbeid i argumentet og kunne endre vurderingen av en rival, ikke bare stå i en ordliste.`)},
    {id:'argument',title:'Argumentrekonstruksjon',paragraphs:art.argument},
    {id:'uenighet',title:'Innvending og svar',paragraphs:[art.objection,art.reply,art.stress]},
    {id:'teorihistorie',title:'Teori og verk',paragraphs:art.theoryNotes.map((note,i)=>`${thinkerNames[i]||thinkerNames[0]} brukes her gjennom ${art.thinkers[i]?.works?.[0]||art.thinkers[0].works[0]}, ikke som navnegjetting. ${note} Sammenligningen er relevant fordi posisjonen angriper eller bærer et bestemt premiss i artikkelens hoveddebatt.`)},
    {id:'metode',title:'Metode og kontrollspørsmål',paragraphs:[`${methodTitle} er hovedgrepet. ${art.methodNote} Analysen skal produsere et konkret mellomledd – for eksempel ${a.method.data_forms.join(', ')} – slik at leseren kan kontrollere hvordan premiss, evidens og konklusjon henger sammen.`,`${art.methodBoundary} Metodebegrensningen er derfor en del av resultatet: analysen skal markere når den går fra historisk verkfortolkning til begrepsanalyse, fra empirisk premiss til filosofisk inferens eller fra beskrivelse til normativ vurdering.`]},
    {id:'case',title:'Anvendelse på et dokumentert case',paragraphs:[art.case,`${art.caseTest} Et dokumentert case skal ikke illustrere teorien ved ren analogi; det skal inneholde nok materiale til at minst to rivaliserende posisjoner kan gi forskjellige, etterprøvbare analyser av samme premisser.`]},
    {id:'kilder',title:'Kildebruk og evidensgrenser',paragraphs:[`${sourceTitles.join('; ')} er de tre emnespesifikke sekundærkildene som bærer denne artikkelens kontroll. ${art.sourceNote} Primærverkene ${art.thinkers.slice(0,3).map(t=>t.works[0]).join('; ')} brukes når påstanden gjelder den navngitte filosofens egen argumentasjon.`,`${art.empiricalBoundary} Kildehierarkiet er dermed asymmetrisk: filosofi- og verk-kilder kan dokumentere argumenter og begrepshistorie, men en konkret lokal, juridisk, fysisk eller statistisk faktapåstand trenger en kilde som faktisk undersøker det forholdet.`]},
    {id:'avgrensning',title:'Hva analysen ikke etablerer',paragraphs:[art.limit,`${art.mastery} Det er nivået som kreves for university depth her. Artikkelen hevder ikke å gjøre videre forskning overflødig; den etablerer et robust hovedfelt med klare rivaler, verk, begreper og evidensgrenser som kan vedlikeholdes og utvides uten at grunnstrukturen blir falskt «komplett».`]}
  ];
};

const newArticles=[];
for(const a of AREAS){
  for(const art of a.articles){
    art.thinkers.forEach(t=>ensureThinker(t,a,art));
    const sections=proseSections(a,art);
    const allProse=sections.flatMap(s=>s.paragraphs||[]).join(' ');
    const wordCount=words(allProse);
    if(wordCount<1200) throw new Error(`${art.id} has only ${wordCount} words; university gate requires 1200`);
    const sourceIds=art.sources;
    if(sourceIds.length<3||!sourceIds.every(id=>sourceById.has(id))) throw new Error(`${art.id} source resolution failed`);
    const claim=(suffix,type,text)=>({id:`${art.id}_claim_${suffix}`,type,text,source_ids:sourceIds});
    const claims=[
      claim('problem','problem_framing',sections[0].paragraphs[0]),
      claim('position','position_reconstruction',sections[2].paragraphs[0]),
      claim('rival','rival_position',sections[3].paragraphs[0]),
      claim('distinction','concept_distinction',sections[1].paragraphs[0]),
      claim('history','historical_position',sections[4].paragraphs[0]),
      claim('method','methodological',sections[5].paragraphs[0]),
      claim('limit','limitation',sections[8].paragraphs[0])
    ];
    const doc={
      schema:'history_go_fagverk_filosofi_article_v1',version:'1.0.0',subject_id:'filosofi',id:art.id,title:art.title,domain_id:a.id,area_id:a.area_id,level:art.level,status:'complete',editorial_quality:'university_depth_reviewed',canonical_definition:art.definition,
      concept_ids:art.concepts.map(c=>c.id),method_ids:[a.method.id,...art.methods],theory_hook_ids:[art.hook],thinker_refs:art.thinkers.map(t=>t.id),primary_work_refs:art.thinkers.map(t=>t.works[0]),source_ids:sourceIds,claims,sections,
      quality:{word_count:wordCount,section_count:sections.length,paragraph_count:sections.reduce((n,s)=>n+s.paragraphs.length,0),argument_reconstruction:true,rival_position:true,method_limit:true,source_boundaries:true,concepts_written_out:true,place_boundary:true,editorial_polish:true,tradition_specific_relevance:true,review_state:'university_depth_reviewed',reviewed_against_university_gate:true,substantive_argument_reconstruction:true,topic_specific_sources:true},
      university_quality:{schema:'history_go_filosofi_university_quality_v1',review_version:'3.0.0',reviewed_at:UPDATED,debate:art.debate,debate_thinkers:art.thinkers.map(t=>t.name),required_anchors:art.anchors,substantive_argument:true,real_rival:true,primary_work_grounding:true,topic_specific_secondary_sources:true,generic_template_rejected:true}
    };
    const substantive=sections.filter(s=>['argument','uenighet','teorihistorie'].includes(s.id)).flatMap(s=>s.paragraphs).join(' ').toLocaleLowerCase('nb');
    for(const anchor of art.anchors){ if(!substantive.includes(anchor.toLocaleLowerCase('nb'))) throw new Error(`${art.id} missing anchor in substantive sections: ${anchor}`); }
    writeJson(articlePath(art.id),doc);newArticles.push(doc);
    const emne={emne_id:art.id,subject_id:'filosofi',domain:a.id,area_id:a.area_id,area_label:a.title,level:art.level,title:art.title,status:'active',definition:art.definition,why_it_matters:`${art.title} er et selvstendig universitetsfeltproblem som gjør det mulig å analysere navngitte rivaler, verk og argumenter uten å redusere ${a.title.toLocaleLowerCase('nb')} til et tilfeldig underpunkt i et annet fagområde.`,core_concepts:art.concepts.map(c=>c.id),method_ids:[a.method.id,...art.methods],theory_hook_ids:[art.hook],quiz_priority:'high',direct_quiz_ok:true,question_moves:['rekonstruer et navngitt argument med premisser og konklusjon','sammenlign rivaliserende posisjoner på samme problem','anvend teoriene på et dokumentert case og skill empiriske premisser fra filosofisk inferens'],place_relevance:a.places};
    existing.emner.push(emne);emneById.set(art.id,emne);
  }
}

for(const a of AREAS){
  const focus=a.articles.map(x=>x.title);
  const hooks=a.articles.map(art=>({id:art.hook,title:art.title,definition:art.definition,canon:{thinkers:art.thinkers.map(t=>({id:t.id,name:t.name,why:`${t.name} bærer en eksplisitt posisjon i ${art.title.toLocaleLowerCase('nb')} gjennom et navngitt verk og et argument som kan rekonstrueres.`,tier:t.tier||'core',works:t.works}))},emne_ids:[art.id],concept_ids:art.concepts.map(c=>c.id),best_place_types:a.places,avoid_place_types:['sted uten dokumentert filosofisk, institusjonell eller faglig relevans'],set_phase_fit:['bridge_facts_theory','late_theory'],recommended_method_ids:[a.method.id,...art.methods.slice(0,2)],generator_constraints:{avoid_name_guessing:true,require_argument:true,require_documented_anchor:true}}));
  const cat={id:a.id,title:a.title,tagline:a.tagline,definition:a.tagline,focus,emne_ids:a.articles.map(x=>x.id),best_place_types:a.places,topic_hooks:hooks};
  if(categoryById.has(a.id)) throw new Error(`Category already exists ${a.id}`);
  existing.fagkart.categories.push(cat);categoryById.set(a.id,cat);
  const module={module_id:`kur_filosofi_${String(existing.pensum.modules.length+1).padStart(2,'0')}_${a.id}`,title:a.title,level:3,estimated_minutes:75,mål:[`Kunne definere og skille de sentrale begrepene i ${a.title.toLocaleLowerCase('nb')}.`,'Kunne rekonstruere minst ett reelt argument og formulere en presis rival eller innvending.','Kunne bruke navngitte primærverk og emnespesifikke sekundærkilder med tydelige evidensgrenser.','Kunne anvende rivaliserende teorier på et dokumentert case uten å blande empirisk fakta og filosofisk inferens.'],emner:a.articles.map(x=>x.id),konsepter:a.articles.flatMap(x=>x.concepts.map(c=>c.id)),topic_hooks:a.articles.map(x=>x.hook),metoder:[a.method.id,'met_filosofi_argumentrekonstruksjon','met_filosofi_begrepsanalyse','met_filosofi_moteksempel'],status:'active'};
  existing.pensum.modules.push(module);moduleIds.add(module.module_id);
}

existing.concepts.counts.total=existing.concepts.concepts.length;
existing.thinkers.counts={total:existing.thinkers.thinkers.length,active:existing.thinkers.thinkers.filter(x=>x.status==='active').length,contextual:existing.thinkers.thinkers.filter(x=>x.status==='contextual').length};
existing.sources.version='3.0.0';

for(const a of AREAS){
  const articles=a.articles.map(art=>newArticles.find(x=>x.id===art.id));
  const sourceIds=uniq(articles.flatMap(x=>x.source_ids));
  const claimIds=articles.flatMap(x=>x.claims.map(c=>c.id));
  const chapterSections=[
    {id:'oversikt',title:'Fagområdets problem',paragraphs:[`${a.title} er materialisert som et selvstendig hovedområde fordi universitetsbenchmarken behandler feltet som en etablert filosofisk disiplin og den tidligere trettenområdestrukturen ikke ga feltet egen canonical dekning. De to artiklene er ${a.articles.map(x=>x.title).join(' og ')}.`,`${a.tagline} Kapittelet er en lesesti: de fullstendige argumentrekonstruksjonene, rivalene, primærverkene, metodene og evidensgrensene ligger i de selvstendige emneartiklene og må bestå samme university-depth-port som resten av Filosofi.`]},
    {id:'emner',title:'Emnene',paragraphs:articles.map(doc=>`${doc.title} har ${doc.quality.word_count} ord, tre eksplisitt utskrevne begreper, ${doc.claims.length} claimsporede kontrollpunkter og ${doc.source_ids.length} emnespesifikke sekundærkilder. Artikkelen rekonstruerer en navngitt debatt og består ikke på struktur alene.`)},
    {id:'metode',title:'Felles metodekrav',paragraphs:[`${a.method.title} brukes sammen med argumentrekonstruksjon og begrepsanalyse. Metoden krever et synlig mellomledd og skiller eksplisitt mellom hva en primærtekst hevder, hva en sekundærkilde fortolker og hva et dokumentert case faktisk viser.`,`Fagområdets viktigste begrensning er at filosofiske teorier ikke kan fungere som evidens for lokale, juridiske, fysiske eller statistiske fakta. Slike premisser må dokumenteres separat før de brukes i argumentet.`]},
    {id:'videre',title:'Anvendelse og videre lesning',paragraphs:[`Et egnet case må være dokumentert godt nok til at de to artiklenes rivaler kan anvendes på samme premisser. Stedsrelevans er derfor bundet til ${a.places.join(', ')}, ikke til en antakelse om at ethvert sted automatisk er filosofisk relevant.`,`De åpne sekundærkildene i fagområdet er ${sourceIds.map(id=>sourceById.get(id).title).join('; ')}. Primærverkene ligger eksplisitt i artikkelobjektene og brukes til verkspesifikke rekonstruksjoner.`]}
  ];
  const chapterId=a.id.replaceAll('_','-');
  const chapter={schema:'history_go_fagverk_filosofi_chapter_v1',version:'1.0.0',subject_id:'filosofi',id:`filosofi-${chapterId}`,title:a.title,domain_id:a.id,status:'complete',article_ids:a.articles.map(x=>x.id),emne_ids:a.articles.map(x=>x.id),source_ids:sourceIds,claim_ids:claimIds,sections:chapterSections,quality:{article_coverage:articles.length,word_count:words(chapterSections.flatMap(s=>s.paragraphs).join(' ')),all_articles_complete:true,editorial_polish:true,source_relevance_rebuilt:true,major_field_benchmark:true}};
  const file=chapterPath(chapterId);writeJson(file,chapter);
  existing.registry.chapters.push({id:chapter.id,title:chapter.title,file,primary_domain_id:a.id,chapter_role:'core',emne_ids:chapter.emne_ids,article_ids:chapter.article_ids,claimsFile:P.registry});
}

