const completeTest=`import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nconst ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');\nconst json=(p)=>JSON.parse(fs.readFileSync(path.join(ROOT,p),'utf8'));\nconst words=(s)=>String(s||'').trim().split(/\\s+/).filter(Boolean).length;\nconst registry=json('${P.registry}');\nconst concepts=json('${P.concepts}');\nconst methods=json('${P.methods}');\nconst sources=json('${P.sources}');\nconst completion=json('${P.completion}');\nconst coverage=json('${P.coverage}');\nconst audit=json('${P.completeAudit}');\nconst sourceIds=new Set(sources.sources.map((s)=>s.id));\nconst conceptIds=new Set(concepts.concepts.map((c)=>c.id));\nconst methodIds=new Set(methods.methods.map((m)=>m.method_id));\nconst articles=registry.articles.map((row)=>json(row.file));\nconst chapters=registry.chapters.map((row)=>json(row.file));\nconst reviewed=articles.filter((article)=>article.editorial_quality==='university_depth_reviewed');\nconst E=coverage.expected_counts;\ntest('Filosofi beholder eksakt canonical dekning uten å forveksle dekning med universitetsdybde',()=>{\n assert.equal(articles.length,E.articles);assert.equal(chapters.length,E.chapters);assert.equal(conceptIds.size,E.concepts);assert.equal(methodIds.size,E.methods);\n assert.equal(completion.standalone_article_count,E.articles);assert.equal(completion.chapter_count,E.chapters);assert.equal(completion.canonical_concept_count,E.concepts);assert.equal(completion.canonical_method_count,E.methods);\n});\ntest('alle artikler har solid strukturell baseline, men struktur er ikke kvalitetsproxy',()=>{for(const article of articles){\n const prose=article.sections.flatMap((s)=>s.paragraphs||[]);assert.ok(words(prose.join(' '))>=1200,article.id+' er for kort');assert.ok(article.sections.length>=9,article.id+' mangler seksjoner');assert.ok(prose.length>=20,article.id+' mangler fagavsnitt');assert.ok(article.claims.length>=5,article.id+' har for få claims');assert.ok(article.source_ids.length>=3,article.id+' mangler kildedybde');assert.ok(article.source_ids.every((id)=>sourceIds.has(id)),article.id+' har ukjent kilde');assert.ok(article.method_ids.length>=1&&article.method_ids.every((id)=>methodIds.has(id)),article.id+' har uløst metode');assert.ok(article.concept_ids.length>=1&&article.concept_ids.every((id)=>conceptIds.has(id)),article.id+' har uløst begrep');assert.ok(article.claims.every((c)=>c.source_ids?.length>=2&&c.source_ids.every((id)=>sourceIds.has(id))),article.id+' har claim uten løste kilder');for(const id of ['argument','uenighet','metode','avgrensning'])assert.ok(article.sections.some((s)=>s.id===id),article.id+' mangler '+id);\n}});\ntest('completion er bare grønn når alle artikler er individuelt universitetsreviewet og feltbenchmarken er komplett',()=>{\n assert.equal(completion.reviewed_article_count,reviewed.length);assert.equal(completion.remaining_university_review_count,articles.length-reviewed.length);assert.equal(completion.complete_ready,reviewed.length===articles.length&&coverage.complete_ready);assert.equal(audit.gates.completeReadyHonest,true);assert.equal(audit.gates.universityDepthReviewedAllArticles,true);assert.equal(audit.gates.majorUniversityFieldsCovered,true);\n});\ntest('alle canonicale begreper er skrevet ut i faktisk artikkelprosa',()=>{const covered=new Set();for(const article of articles){const section=article.sections.find((s)=>s.id==='begreper');assert.ok(section,article.id+' mangler begrepsseksjon');assert.equal(section.paragraphs.length,article.concept_ids.length,article.id+' har feil begrepsavsnitt');article.concept_ids.forEach((id,i)=>{const label=concepts.concepts.find((c)=>c.id===id)?.label;assert.ok(section.paragraphs[i].toLocaleLowerCase('nb').includes(label.toLocaleLowerCase('nb')),article.id+' skriver ikke ut '+label);covered.add(id);});}assert.deepEqual([...covered].sort(),[...conceptIds].sort());});\ntest('kapitlene eier alle emneartikler uten duplikat',()=>{const ids=chapters.flatMap((c)=>c.article_ids||[]);assert.equal(ids.length,E.articles);assert.equal(new Set(ids).size,E.articles);assert.deepEqual([...new Set(ids)].sort(),articles.map((a)=>a.id).sort());});\ntest('Filosofi-kildene er inspectable og rollebeskrevet',()=>{for(const source of sources.sources){assert.match(source.url,/^https:\\/\\//,source.id+' mangler inspectable URL');assert.ok(source.publisher?.length>=3,source.id+' mangler publisher');assert.ok(source.use?.length>=40,source.id+' mangler evidensrolle');}});\ntest('completion-auditen skiller strukturelle porter, universitetsdybde og feltdekning',()=>{for(const gate of ['canonicalCountsExact','allEmnersHaveStandaloneArticles','allConceptsWrittenOut','allDomainsHaveChapters','minimumArticleDepth','minimumSourceDepth','completeReadyHonest','majorUniversityFieldsCovered'])assert.equal(audit.gates[gate],true,'gate '+gate+' skal være grønn');assert.equal(audit.summary.standalone_article_count,E.articles);assert.equal(audit.summary.canonical_concept_count,E.concepts);assert.equal(audit.summary.chapter_count,E.chapters);});\n`;
writeText(P.completeTest,completeTest);

const phase3Test=`import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nimport { auditFilosofiPhase3 } from '../scripts/audit-fagverk-filosofi-phase3.mjs';\nconst ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');\nconst json=(p)=>JSON.parse(fs.readFileSync(path.join(ROOT,p),'utf8'));\nconst coverage=json('${P.coverage}');const thinkers=json('${P.thinkers}');const E=coverage.expected_counts;\ntest('Filosofi er materialisert og auditert som komplett major-field Fase 3-fag',()=>{const {report}=auditFilosofiPhase3();assert.equal(report.subject.id,'filosofi');assert.equal(report.subject.schemaFamily,'foundation_v1');assert.equal(report.subject.adapter,'standard');assert.equal(report.subject.navigationStatus,'materialized');assert.equal(report.subject.assessmentStatus,'audited');assert.equal(report.subject.editorialStatus,'complete');assert.equal(report.subject.nextGate,'maintenance_source_refresh_and_place_case_expansion');assert.equal(report.summary.domainCount,E.domains);assert.equal(report.summary.emneCount,E.articles);assert.equal(report.summary.methodCount,E.methods);assert.equal(report.summary.mappingCount,E.articles);assert.equal(report.summary.hookCount,E.hooks);assert.equal(report.summary.courseModuleCount,E.domains);assert.equal(report.summary.conceptCount,E.concepts);assert.equal(report.summary.registeredChapterCount,E.chapters);assert.equal(report.summary.thinkerCount,thinkers.thinkers.length);});\ntest('Filosofi beholder fagkart-eide områder og pensum som progresjonslag',()=>{const {report,model}=auditFilosofiPhase3();assert.deepEqual(report.canonicalDomainOrder,${JSON.stringify(existing.fagkart.categories.map(x=>x.id))});assert.ok(model.domains.every((domain)=>domain.sourceKind==='fagkart_category'));assert.equal(Object.values(report.domainEmneCounts).reduce((sum,count)=>sum+count,0),E.articles);assert.equal(report.gates.courseModulesRemainProgressionOnly,true);});\ntest('Filosofi løser emner, metoder, hooks, begreper og teoretikere',()=>{const {report,model}=auditFilosofiPhase3();assert.equal(model.emners.length,E.articles);for(const gate of ['allActiveEmnersMapped','allCourseModulesCoverCanonicalEmners','allMethodReferencesResolved','allConceptReferencesResolved','allThinkerReferencesResolved'])assert.equal(report.gates[gate],true);});\ntest('Filosofi låser argument-first, kildekrav, global kanon og konsistent sluttstatus',()=>{const {report}=auditFilosofiPhase3();assert.equal(report.gates.philosophyPrinciplesLocked,true);assert.equal(report.gates.chapterClaimsNotOverstated,true);assert.equal(report.gates.editorialLifecycleConsistent,true);});\n`;
writeText(P.phase3Test,phase3Test);

const fieldTest=`import test from 'node:test';\nimport assert from 'node:assert/strict';\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\nconst ROOT=path.resolve(path.dirname(fileURLToPath(import.meta.url)),'..');const json=(p)=>JSON.parse(fs.readFileSync(path.join(ROOT,p),'utf8'));\nconst coverage=json('${P.coverage}');const fagkart=json('${P.fagkart}');const pensum=json('${P.pensum}');const emner=json('${P.emner}');const concepts=json('${P.concepts}');const methods=json('${P.methods}');const registry=json('${P.registry}');const completion=json('${P.completion}');const articles=new Map(registry.articles.map(r=>[r.id,json(r.file)]));const domainIds=new Set(fagkart.categories.map(x=>x.id));const E=coverage.expected_counts;\ntest('major-university-field benchmark er eksplisitt, kildeført og ærlig avgrenset',()=>{assert.equal(coverage.status,'major_university_fields_complete');assert.match(coverage.benchmark.primary.url,/^https:\\/\\/www\\.philosophy\\.ox\\.ac\\.uk\\//);assert.match(coverage.scope_definition,/major university fields/i);assert.match(coverage.scope_definition,/ikke at enhver mulig forskningsnisje/i);assert.match(coverage.excluded_scope,/micro-specialties/i);assert.equal(coverage.fields.every(x=>x.coverage==='covered'&&x.domain_ids.length>=1),true);for(const field of coverage.fields)for(const id of field.domain_ids)assert.ok(domainIds.has(id),'benchmarkfelt '+field.field_id+' peker til ukjent '+id);});\ntest('de syv tidligere hullene er egne canonicale hovedområder med universitetsdybde',()=>{assert.deepEqual(coverage.newly_closed_gaps.sort(),${JSON.stringify(NEW_DOMAIN_ORDER.sort())});for(const id of coverage.newly_closed_gaps){const cat=fagkart.categories.find(x=>x.id===id);assert.ok(cat,id+' mangler fagområde');assert.equal(cat.emne_ids.length,2,id+' skal ha to selvstendige emner');assert.equal(cat.topic_hooks.length,2,id+' skal ha to hooks');const module=pensum.modules.find(x=>x.emner?.some(e=>cat.emne_ids.includes(e)));assert.ok(module,id+' mangler pensummodul');for(const emneId of cat.emne_ids){const art=articles.get(emneId);assert.ok(art,emneId+' mangler artikkel');assert.equal(art.editorial_quality,'university_depth_reviewed');assert.equal(art.university_quality?.reviewed_against_university_gate??true,true);assert.equal(art.university_quality?.real_rival,true);assert.equal(art.source_ids.length>=3,true);}}});\ntest('feltbenchmarkens forventede tall matcher alle canonicale kilder',()=>{assert.equal(fagkart.categories.length,E.domains);assert.equal(pensum.modules.length,E.domains);assert.equal(emner.length,E.articles);assert.equal(registry.articles.length,E.articles);assert.equal(registry.chapters.length,E.chapters);assert.equal(concepts.concepts.length,E.concepts);assert.equal(methods.methods.length,E.methods);assert.equal(fagkart.categories.flatMap(x=>x.topic_hooks||[]).length,E.hooks);});\ntest('complete krever både 100 prosent universitetreview og 100 prosent benchmarkdekning',()=>{const reviewed=[...articles.values()].filter(a=>a.editorial_quality==='university_depth_reviewed').length;assert.equal(reviewed,E.articles);assert.equal(completion.reviewed_article_count,E.articles);assert.equal(completion.remaining_university_review_count,0);assert.equal(completion.complete_ready,true);assert.equal(coverage.complete_ready,true);assert.equal(completion.quality_standard,'substantive_university_philosophy_v3_major_fields');});\n`;
writeText(P.fieldTest,fieldTest);

